def lease_clock_domain_check() -> None:
    """租约/调度按秒、墙钟按毫秒：跨域必须走 `lease_clock`，超时升级必须有读者（V12 §18 TX8）。"""
    wiring = production_text((ROOT / LEASE_WIRING_FILE).read_text(encoding="utf-8"))
    scheduler = (ROOT / LEASE_SCHEDULER_FILE).read_text(encoding="utf-8")
    scheduler_prod = production_text(scheduler)
    workers_prod = "".join(
        production_text((ROOT / LEASE_WORKERS_FILE).read_text(encoding="utf-8")).split()
    )
    scheduler_worker_prod = "".join(
        production_text((ROOT / SCHEDULER_WORKER_FILE).read_text(encoding="utf-8")).split()
    )
    pipeline_prod = "".join(
        production_text((ROOT / LEASE_EVENT_PIPELINE_FILE).read_text(encoding="utf-8")).split()
    )
    runtime_workers_prod = "".join(
        production_text(
            (ROOT / "crates/qx-runtime/src/messaging_workers.rs").read_text(encoding="utf-8")
        ).split()
    )
    runtime_time_prod = "".join(
        production_text((ROOT / "crates/qx-runtime/src/time.rs").read_text(encoding="utf-8")).split()
    )
    scheduler_domain_prod = "".join(
        production_text(
            (ROOT / "crates/qx-scheduler/src/runtime_support.rs").read_text(encoding="utf-8")
        ).split()
    )
    cases = (ROOT / LEASE_CASE_FILE).read_text(encoding="utf-8")

    check(
        wiring.count("pub(crate) fn lease_clock(") == 1
        and "qx_runtime::lease_clock(timestamp_ms)" in _fn_body(
            wiring, "pub(crate) fn lease_clock("
        )
        and runtime_time_prod.count("pubfnlease_clock(timestamp_ms:u64)->u64") == 1
        and "timestamp_ms/1_000" in _fn_body(
            runtime_time_prod, "pubfnlease_clock("
        ),
        "毫秒墙钟到租约秒只有一个换算入口，且它确实除以 1000",
        "lease_clock 定义数或换算式变了",
    )
    def tight(path: str) -> str:
        # 尾逗号归一：rustfmt 把长实参拆成多行时会给最后一个实参补上尾逗号，按字面比对的
        # 判据立刻读出 0 处 —— 本轮 paper_worker.rs 的 `ack_command_at` 秒域判据就是这么红的。
        # 判据要认的是「第 4 个实参拿的是哪把时钟」，不是换行与尾逗号（见 `_collapsed_code`）。
        return _collapsed_code(
            production_text((ROOT / path).read_text(encoding="utf-8")),
            tight=True,
        )

    bad_units = [
        f"{path}: 缺 {ok}" if ok not in tight(path) else f"{path}: 退回 {bad}"
        for path, ok, bad in LEASE_CALL_SITES
        if ok not in tight(path) or bad in tight(path)
    ]
    strategy_lease_code = tight(LEASE_WORKERS_FILE)
    strategy_lease_requirements = (
        "letstrategy_lease_owner=strategy_job_lease_owner(&registered_id);",
        "letmutlease=matchqueue.claim(queued.run.run_id,&strategy_lease_owner,lease_now,strategy_job_lease_seconds)",
        "letfinalize_now=lease_clock(runtime_timestamp_ms());",
        "letevaluation_lease_now=lease_clock(runtime_timestamp_ms());",
        "letcommit_lease_now=lease_clock(runtime_timestamp_ms());",
        "letfailure_lease_now=lease_clock(runtime_timestamp_ms());",
        "queue.claim(queued.run.run_id,&strategy_lease_owner,commit_lease_now,strategy_job_lease_seconds)",
        "queue.ack_at(queued.run.run_id,&strategy_lease_owner,lease.fencing_token,lease_clock(runtime_timestamp_ms()))",
        "ifstrategy_config.python_module.is_some(){Some(SandboxExecutionPolicy::from_env()?)}else{None}",
        "execution_policy.as_ref().is_some_and(SandboxExecutionPolicy::sandbox_enabled)",
        "strategy_config.python_timeout_ms.saturating_add(999)/1000",
        "ifremote_strategy{240}else{0}",
        ".saturating_add(60)",
        ".max(30)",
    )
    if not all(term in strategy_lease_code for term in strategy_lease_requirements):
        bad_units.append(f"{LEASE_WORKERS_FILE}: 策略租约 owner、fresh-time claim/ack 或请求/E2B 启动预算断链")
    if strategy_lease_code.count("queue.claim(queued.run.run_id,&strategy_lease_owner,") < 5:
        bad_units.append(f"{LEASE_WORKERS_FILE}: 策略 run 开始/恢复/执行/提交/失败各阶段没有逐段刷新 owner lease")
    scheduler_stale_lease_code = tight(LEASE_SCHEDULER_FILE)
    stale_lease_requirements = (
        "queue.claim(lease.queued.run.run_id,lease.lease_owner,claim_now,lease.lease_seconds)",
        "lease.queue.ack_at(lease.queued.run.run_id,lease.lease_owner,current_lease.fencing_token,lease_clock(runtime_timestamp_ms()))",
    )
    if not all(term in scheduler_stale_lease_code for term in stale_lease_requirements):
        bad_units.append(f"{LEASE_SCHEDULER_FILE}: stale snapshot ack 未重新确认当前 fencing lease")
    check(
        not bad_units,
        "作业队列与命令队列使用秒域时钟；策略租约覆盖 Python 请求与 E2B 启动预算",
        f"; ".join(bad_units),
    )
    strategy_policy_code = tight("crates/qx-cli/src/strategy_host/execution_policy.rs")
    strategy_worker_start = strategy_lease_code.find(
        "SandboxExecutionPolicy::from_env()?"
    )
    worker_host_start = strategy_lease_code.find("qx_service::worker_host::run_worker(")
    check(
        "QX_PYTHON_STRATEGY_SANDBOX_REQUIRED" in strategy_policy_code
        and "ifsandbox_required&&provider==StrategySandboxProvider::Local" in strategy_policy_code
        and "SandboxExecutionPolicy::from_env()?" in tight(
            "crates/qx-cli/src/strategy_host.rs"
        )
        and strategy_worker_start >= 0
        and worker_host_start > strategy_worker_start,
        "strategy-worker 的宿主可强制要求沙箱，缺失/local provider 在工作进程启动前拒绝",
        "强制开关缺失、强制本地拒绝缺失，或策略 worker 启动早于策略执行策略校验",
    )
    bad_acks = [
        f"{path}: ack_command_at 秒域写法 {tight(path).count(LEASE_ACK_PACKED.format(owner=owner, now='lease_now'))}/{expected}"
        for path, owner, expected in LEASE_ACK_OWNERS
        if tight(path).count(LEASE_ACK_PACKED.format(owner=owner, now="lease_now")) != expected
        or LEASE_ACK_PACKED.format(owner=owner, now="now") in tight(path)
    ]
    check(
        not bad_acks,
        "执行 worker 收尾确认与领取用同一把秒域时钟，作业不会被自己的租约判过期",
        f"; ".join(bad_acks),
    )
    bad_enqueues = []
    for path, expected in LEASE_ENQUEUE_SITES:
        text = tight(path)
        # 秒域写法只有这两种形状（就地换算与提前换算）；第三种写法就是往秒域队列里塞毫秒。
        lease_form = (
            text.count(".enqueue_command(command.clone(),lease_now)")
            + text.count(".enqueue_command(command,lease_clock(")
            + text.count(".enqueue_command(command,qx_runtime::lease_clock(")
        )
        if text.count(".enqueue_command(") != expected or lease_form != expected:
            bad_enqueues.append(f"{path} 秒域入队 {lease_form}/{expected}")
    check(
        not bad_enqueues,
        "八处命令队列入口全部按秒域写时间戳，且没有第九处绕开换算（同一队列混单位会让出队顺序倒置）",
        f"{'；'.join(bad_enqueues)}",
    )
    cli_relay_output = production_text(
        (ROOT / "crates/qx-cli/src/event_pipeline.rs").read_text(encoding="utf-8")
    )
    check(
        pipeline_prod.count(".pump_once(qx_runtime::lease_clock(") == 2
        and ".pump_once(now" not in pipeline_prod
        and ".pump_once(runtime_timestamp_ms()" not in pipeline_prod
        and cli_relay_output.count("parked={}") == 2
        and runtime_workers_prod.count(".pump_once(lease_clock(") == 1
        and runtime_workers_prod.count("parked={}") == 1,
        "三个 Outbox relay 出口都把墙钟换算成秒后才比较租约，并把停在门后的条数一起念出来（V13 R5）",
        f"service pump_once 秒域写法 {pipeline_prod.count('.pump_once(qx_runtime::lease_clock(')}/2、"
        f"runtime pump_once 秒域写法 {runtime_workers_prod.count('.pump_once(lease_clock(')}/1、"
        f"parked 自报 {pipeline_prod.count('parked={}')}+{runtime_workers_prod.count('parked={}')}（期望 2+1）——"
        "单次批处理退 0 只代表这一页搬完了，不念 parked 就是把「还剩 N 条毒事件」报成「中继干净」",
    )
    dispatch = _fn_body(scheduler_prod, "pub(crate) fn dispatch_scheduled_jobs(")
    dispatch_tight = "".join(dispatch.split())
    scheduler_tests = (ROOT / "crates/qx-scheduler/src/active_run_tests.rs").read_text(encoding="utf-8")
    check(
        "letactive_run_ids=scheduler.active_run_ids().collect::<Vec<_>>();" in dispatch_tight
        and "forrun_idinactive_run_ids" in dispatch_tight
        and "scheduler.is_timed_out(run_id,lease_now)" in dispatch_tight
        and "scheduler.mark_timed_out(run_id,lease_now)" in dispatch_tight
        and "scheduler.runs()" not in dispatch_tight
        and "fn active_run_index_tracks_lifecycle_and_rebuilds_after_restore()" in scheduler_tests
        and 'stored.contains("active_run_ids")' in scheduler_tests
        and "restored.retry_run_at(first.run_id, u64::MAX)" in scheduler_tests
        and "restored.mark_timed_out(timed.run_id, 230)" in scheduler_tests,
        "调度 tick 只遍历活动运行索引并升级超时作业，不克隆终态历史",
        "升级循环缺失，或活动运行索引的恢复/成功/失败重试/超时收口缺少行为证据",
    )
    check(
        "start_run_at(&job_id,trading_day,manifest.digest(),lease_now" in dispatch_tight
        and "start_run_at(&job_id,trading_day,manifest.digest(),now" not in dispatch_tight
        and "enqueue(job,run,lease_now)" in dispatch_tight,
        "派发写入的 JobRun 与入队时间戳都在秒域，与升级判定同一把时钟",
        "派发消息又拿毫秒当租约时钟",
    )
    check(
        "Err(qx_scheduler::SchedulerError::NotReady(_))" in dispatch
        and "skipped += 1;" in dispatch,
        "并发键被占用只跳过本轮，不让一个作业打死整个调度器",
        "NotReady 又变成整轮 Err",
    )
    live = _fn_body(scheduler_domain_prod, "pubfnlive_strategy_job(")
    live_tight = "".join(live.split())
    live_adapter = _fn_body(scheduler_prod, "pub(crate) fn live_strategy_job(")
    check(
        "deadline_ts:lease_now.saturating_add(job.timeout_seconds)" in live_tight
        and "60_000" not in live_tight
        and "timeout_seconds:LIVE_STRATEGY_TIMEOUT_SECONDS" in live_tight
        and "started_ts:lease_now" in live_tight
        and "qx_scheduler::live_strategy_job(" in live_adapter
        and "lease_now: lease_clock(now)" in live_adapter,
        "实时策略作业的运行记录以秒填写，deadline 直接由 timeout_seconds 推出",
        "运行记录退回毫秒 deadline",
    )
    check(
        'queued={}timed_out={}skipped={}"' in scheduler_worker_prod
        and "dispatch.timed_out" in scheduler_worker_prod,
        "超时升级数量对运维可见，不是只在状态文件里默默变化",
        "调度播报少了 timed_out 一栏",
    )
    missing_cases = [name for name in LEASE_CASES if f"fn {name}(" not in cases]
    check(
        not missing_cases
        and "assert_eq!(takeover.fencing_token, lease.fencing_token + 1);" in cases
        and "assert_eq!(run.status, JobStatus::NeedsIntervention);" in cases
        and "assert_eq!(mid.timed_out, 0);" in cases
        and "assert_eq!(late.timed_out, 1);" in cases
        and "assert_eq!(late.queued, 1" in cases,
        "租约存活、未到期不误判、超时升级、并发键重新派发四断言各有用例钉住",
        f"缺用例 {missing_cases} 或断言被删/改向",
    )


def control_plane_honesty_check() -> None:
    """控制面按 role 找 worker、只读运维端点按磁盘读现状、可用值只列一份（V11 S1/S2/S3/S5/S6）。"""
    contract = (ROOT / "crates/qx-cli/src/strategy_contract.rs").read_text(encoding="utf-8")
    workers = "\n".join(
        (ROOT / path).read_text(encoding="utf-8")
        for path in (
            "crates/qx-cli/src/workers/scheduler_worker.rs",
            "crates/qx-cli/src/workers/strategy_worker.rs",
        )
    )
    api = (ROOT / "crates/qx-api/src/lib.rs").read_text(encoding="utf-8")
    assembly = (ROOT / "crates/qx-service/src/api_host.rs").read_text(encoding="utf-8")
    api_builder = (ROOT / "crates/qx-cli/src/api_service/api_service_builder.rs").read_text(
        encoding="utf-8"
    )
    cli_backends = (ROOT / "crates/qx-cli/src/configured_backends.rs").read_text(encoding="utf-8")
    service_backends = (ROOT / "crates/qx-service/src/configured_backends.rs").read_text(encoding="utf-8")
    cli_runtime_wiring = (ROOT / "crates/qx-cli/src/runtime_wiring.rs").read_text(encoding="utf-8")
    worker_metrics = (ROOT / "crates/qx-service/src/worker_metrics.rs").read_text(encoding="utf-8")
    api_host = (ROOT / "crates/qx-service/src/api_host.rs").read_text(encoding="utf-8")
    http_host = (ROOT / "crates/qx-service/src/http_host.rs").read_text(encoding="utf-8")
    init = (ROOT / "crates/qx-cli/src/init_project.rs").read_text(encoding="utf-8")
    help_text = (ROOT / "crates/qx-cli/src/cli_help.rs").read_text(encoding="utf-8")
    identity_cases = (
        ROOT / "crates/qx-cli/tests/unit/runtime_api_worker_identity.rs"
    ).read_text(encoding="utf-8")
    live_cases = (ROOT / "crates/qx-cli/tests/unit/api_query_models_live.rs").read_text(
        encoding="utf-8"
    )

    check(
        'supervisor.spawn_worker("api"' not in contract
        and "qx_service::http_host::serve_api(" in contract
        and "supervisor.spawn_worker(&api_worker_id" not in contract
        and _fn_body(http_host, "pub fn serve_api(").count("supervisor.spawn_worker(&api_worker_id") == 2
        and contract.count("fn configured_api_worker_id(") == 1
        and "qx_service::http_host::configured_api_worker_id(config)" in contract
        and 'worker.enabled && worker.role == WorkerRole::Api' in http_host
        and "if workers.next().is_some()" in http_host
        and ".ok_or_else(" in http_host[http_host.find("pub fn configured_api_worker_id(") :],
        "API worker 身份与明文/mTLS API host 由 qx-service 按唯一启用 role 装配，CLI serve 仅委托、不回落字面量",
        "API host lifecycle 或 worker role 解析仍留在 CLI、未检查唯一性，或字面量 api 回到 spawn 点",
    )
    check(
        all(
            f"fn {name}(" in identity_cases
            for name in (
                "renamed_api_worker_is_the_one_the_supervisor_accepts",
                "api_worker_lookup_fails_closed_without_an_enabled_one",
            )
        ),
        "S1 用例在位：改名后的 api worker 仍能注册，而字面量必须失败",
        "缺用例或改名，用例不再能区分字面量与按 role 解析",
    )
    check(
        api.count("pub fn with_query_models_provider") == 1
        and api.count("fn query_models(&self)") == 1
        and assembly.count("pub fn attach_query_models_provider(") == 1
        and "crate::api_read_model::query_api_models(&config)" in assembly,
        "三个只读运维端点装了现读 provider，且 provider 与启动装载共用同一个读点",
        "provider 又回到只读一次，或两条路各写一份读模型构造代码",
    )
    check(
        assembly.count("fn hydrate_api_initial_state_with_market_specs(") == 1
        and "crate::api_read_model::query_api_models(config)?" in assembly
        and "configured_account_event_logs(config)?" in assembly
        and "OutboxRecovery::ReadOnly" in assembly
        and "project_event_log(pipeline.log())" in assembly
        and "initial_api_state_hydrates_persisted_account_events" in api_host
        and "hydrate_api_initial_state_with_market_specs(" in assembly
        and "load_api_account_snapshots_with_market_specs(config, market_specs)?" in assembly
        and "state.project_account_event_log(" not in api_builder
        and "load_api_account_snapshots_with_market_specs(config, market_specs)" not in api_builder,
        "API 启动读模型、账户与默认全局事件投影、账户快照均归 qx-service，且有历史数据启动行为用例",
        "API 初始读状态仍在 CLI 分叉装配，或启动未同步默认全局事件投影/缺少行为用例",
    )
    check(
        all(f"pub fn {name}(" in worker_metrics for name in (
            "worker_metrics_dir", "worker_metrics_path", "write_worker_metrics",
            "read_worker_metrics", "worker_metrics_stale", "force_worker_metrics_down",
            "worker_metrics_unhealthy", "prometheus_label",
        ))
        and "crate::worker_metrics::worker_metrics_dir(config)" in assembly
        and "crate::worker_metrics::read_worker_metrics(" in assembly
        and "pub(crate) use qx_service::worker_metrics::" in cli_runtime_wiring
        and all(f"fn {name}(" not in cli_runtime_wiring for name in (
            "worker_metrics_dir", "worker_metrics_path", "write_worker_metrics",
            "read_worker_metrics", "worker_metrics_stale", "force_worker_metrics_down",
            "worker_metrics_unhealthy", "prometheus_label",
        )),
        "worker metrics 的文件 IO/聚合/过期实现归 qx-service，API builder 直接使用 service，CLI 仅兼容重导出",
        "worker metrics 存在重复实现，或 API builder 仍依赖 CLI 所有权",
    )
    check(
        all(f"pub fn {name}(" in service_backends for name in (
            "configured_control_store", "configured_command_queue", "configured_job_queue",
            "configured_postgres_dsn",
        ))
        and "pub(crate) fn configured_control_store(" not in cli_backends
        and "pub(crate) fn configured_command_queue(" not in cli_backends
        and "pub(crate) fn configured_job_queue(" not in cli_backends
        and "pub(crate) use qx_service::configured_backends::*;" in cli_backends,
        "RuntimeConfig 后端选择（控制状态、命令队列、作业队列）归 qx-service，CLI 只兼容重导出",
        "backend selection remains implemented in the CLI facade or has split definitions",
    )
    routes = api[api.find('("GET", "/scheduler/runs")') : api.find('("GET", "/account/snapshot/diff")')]
    check(
        routes.count("self.query_models()") == 3
        and "self.job_runs()" not in routes
        and "self.ledger_entries()" not in routes
        and "self.reconcile_reports()" not in routes,
        "调度/账簿/对账三个端点全部改读现读结果，读不到就报 503 而不是念启动那份",
        f"三处里仍有回落到 boot 快照的读点：query_models()={routes.count('self.query_models()')}",
    )
    check(
        all(
            f"fn {name}(" in live_cases
            for name in (
                "reconcile_report_endpoint_follows_the_worker_written_file",
                "ledger_endpoint_sees_fills_appended_after_boot",
            )
        ),
        "S3 用例在位：启动之后落盘的报告与成交都必须读得到，两条机制各自验证",
        "用例缺任一条：只剩文件扫描或只剩日志重放，另一条机制回退了无人发现",
    )
    service_poll_host = _text_or_empty(ROOT / "crates/qx-service/src/worker_host.rs")
    check(
        workers.count("qx_service::worker_host::run_polling_worker(&context, once, || {")
        == 2
        and "while !context.should_stop()" in service_poll_host
        and "context.sleep_ms(sleep_ms.max(1));" in service_poll_host,
        "Scheduler 与 Strategy 将 tick 委托给 qx-service 轮询宿主，停机检查与可中断休眠只有一份实现",
        "任一 CLI worker 又复制停机/休眠循环，或共享服务宿主不再读取消令牌",
    )
    profile_line = next(
        (line for line in help_text.splitlines() if "--profile <" in line),
        "",
    )
    listed = (
        sorted(profile_line.split("--profile <", 1)[1].split(">", 1)[0].split("|"))
        if profile_line
        else []
    )
    declared = sorted(
        init[init.find("const INIT_PROFILES") :].split("= [", 1)[1].split("]", 1)[0].split('"')[
            1::2
        ]
    )
    check(
        listed
        == declared
        == [
            "ashare",
            "backtest",
            "base",
            "builtin",
            "ccxt",
            "crypto-paper",
            "crypto-sandbox-acceptance",
            "multi-venue",
            "paper",
            "research-local",
        ]
        and init.count('INIT_PROFILES.join("、")') == 2
        and "可用值：base、paper" not in init,
        "init --profile 的可用值只有一份：help 的表、错误文案与实际接受的集合三处相等",
        f"help={listed} declared={declared}，或错误文案又抄了一份清单",
    )
    release_profiles = _text_or_empty(ROOT / "docs/发布场景与验收入口-V1.md")
    check(
        all(
            profile in release_profiles and f"--profile {profile}" in release_profiles
            for profile in ("research-local", "crypto-paper", "crypto-sandbox-acceptance")
        )
        and '"sandbox": true' in _text_or_empty(ROOT / "deploy/qianxing.ccxt.exchange.example.json")
        and '"QX_CCXT_OKX_API_KEY"' in _text_or_empty(ROOT / "deploy/qianxing.ccxt.exchange.example.json")
        and "live-check` 是 production 配置门禁，不是 sandbox 验收器" in release_profiles,
        "三个首发发布场景均有可复制的 init profile、前置条件与 sandbox 安全边界",
        "profile 文档、示例模板或生产/sandbox 验收边界出现漂移",
    )
    harness = (ROOT / "crates/qx-cli/tests/unit/mod.rs").read_text(encoding="utf-8")
    check(
        harness.count("assert_binary_fresh(&binary);") == 2
        and "fn assert_binary_fresh(" in harness,
        "子进程用例的两条 binary 取用分支都过新鲜度守卫（V11 S6）",
        "守卫只装在 option_env! 取得到值的那条分支上：`cargo test --bin` 走的是回落分支且不重链 "
        "qx-cli.exe，过期 binary 会让子进程断言对着旧行为静默变绿",
    )


