DEV_CYCLE_FORBIDDEN_EDGES = (
    ("qx-execution", "qx-runtime", "qx-runtime --normal--> qx-execution"),
    ("qx-risk", "qx-zhenlu", "qx-zhenlu --normal--> qx-risk"),
)
# 迁走的五份契约用例：搬家不是丢用例，逐名钉在新位置。
