def _rust_fn_body(text: str, name: str) -> str | None:
    """取 `fn <name>(...)` 的函数体（按花括号配对），找不到返回 `None`。"""
    match = re.search(rf"\bfn {re.escape(name)}\s*[(<]", text)
    if match is None:
        return None
    start = text.find("{", match.end())
    if start < 0:
        return None
    depth = 0
    for index in range(start, len(text)):
        char = text[index]
        if char == "{":
            depth += 1
        elif char == "}":
            depth -= 1
            if depth == 0:
                return text[start : index + 1]
    return None


def event_log_append_batch_check() -> None:
    """P1-1 / DD-2 / §7 M2：EventLog 写侧单事务批量追加（`append_batch`）。

    此前写侧只有整份 `save`：SQLite 参考后端每次追加都要把已落库的 N 条事件读回来逐行比对
    （`load_event_log`），写放大随 N 线性增长（G4）；而 Kernel 侧逐条 `append_checked` 在中途
    失败时会把前半批留在日志里——调用方以为整批被拒、实际写进一半（半个事务）。六颗分别钉：
    ① Kernel 有 `append_batch` 且单条/批量路径共用 `validate_append_event`（校验规则单源；owned 单条追加可直接移动事件）；
    ② `digest()` 走 `digest_of_prefix()`（前缀摘要与全量摘要同源，增量核对才成立）；
    ③ SQLite 的增量追加函数在盘且**不调用** `load_event_log`（否则 O(N) 读放大原样回来）；
    ④ `SqliteEventLogStore::append_batch` 在单事务里走增量路径；⑤ 生产写面的 SQLite 分支真的
    调 `append_batch`（不是加了个没人调的方法）；⑥ 原子性与增量性各有一条行为用例在盘。
    """
    sourcing = case_source(EVENT_LOG_SOURCING)
    sqlite = case_source(SQLITE_BACKEND_FILE)
    pipeline = case_source(PIPELINE_FILE)
    check(
        re.search(
            r"pub fn append_batch\(&mut self, batch: &\[Event\]\) -> QxResult<usize>", sourcing
        )
        is not None
        and "fn validate_append_event(" in sourcing
        and sourcing.count("validate_append_event(") >= 3
        and "self.events.push(event);" in sourcing
        and "self.events_well_formed &=" in sourcing
        and "self.max_event_seq =" in sourcing
        and "next_seq_matches" in sourcing,
        "Kernel append_batch/append_checked 单源，并在追加时维护 EventLog 校验快路径状态",
        "批量追加未委托单源，或校验缓存未由 append 维护并由 validate 检查",
    )
    check(
        "pub fn digest_of_prefix(&self, len: usize) -> Option<u64>" in sourcing
        and re.search(r"pub fn digest\(&self\) -> u64 \{\s*self\.digest_of_prefix\(", sourcing)
        is not None,
        "全量摘要 digest() 与前缀摘要 digest_of_prefix() 同源（增量核对才有意义）",
        "digest_of_prefix 不在盘，或 digest() 没走它",
    )
    incremental = _rust_fn_body(sqlite, INCREMENTAL_APPEND_FN)
    check(
        incremental is not None and "load_event_log(" not in incremental,
        f"SQLite 增量追加 {INCREMENTAL_APPEND_FN} 不重读整条历史（不调 load_event_log）",
        "函数不在盘" if incremental is None else "函数体里出现 load_event_log(",
    )
    method = _rust_fn_body(sqlite, "append_batch")
    check(
        method is not None
        and INCREMENTAL_APPEND_FN + "(" in method
        and "transaction_with_behavior" in method,
        "SqliteEventLogStore::append_batch 在单事务里走增量追加",
        "方法不在盘，或没走增量路径 / 没开事务",
    )
    check(
        re.search(r"Self::Sqlite\(store\) => store\.append_batch\(", pipeline) is not None,
        "生产写面的 SQLite 分支真的走 append_batch（不是加了个没人调的方法）",
        "pipeline.rs 的 SQLite 分支没有走 append_batch",
    )
    check(
        (ROOT / EVENT_LOG_BATCH_TEST).is_file()
        and SQLITE_APPEND_BATCH_CASE in case_source(SQLITE_EVENT_LOG_TEST),
        "append_batch 的原子性（Kernel）与增量性（SQLite）各有一条行为用例在盘",
        f"缺 {EVENT_LOG_BATCH_TEST} 或 {SQLITE_EVENT_LOG_TEST}::{SQLITE_APPEND_BATCH_CASE}",
    )
    postgres_test = case_source(POSTGRES_EVENT_LOG_ATOMICITY_TEST)
    postgres_write = _rust_fn_body(case_source("crates/qx-storage/src/postgres.rs"), "write_with_outbox")
    check(
        POSTGRES_EVENT_LOG_ATOMICITY_CASE in postgres_test
        and "#[ignore" in postgres_test
        and postgres_write is not None
        and "append_outbox_in_transaction" in postgres_write
        and "transaction.commit()" in postgres_write,
        "PostgreSQL EventLog+Outbox 有冲突回滚与幂等重试集成契约，并由单事务实现",
        "缺 PostgreSQL 原子性契约，或 write_with_outbox 未在单事务内追加并提交 Outbox",
    )


def pipeline_cursor_refresh_check() -> None:
    """P1-2 / §7 M2：`LiveEventPipeline` 改游标增量 refresh（G5 收敛）。

    此前每次 `refresh()` 都把整条共享日志读回来 + 整份重放重建（`rebuild_ledger` +
    `rebuild_runtime_indexes` + 整份替换），而它在**每条外部事实之前**都会被调一次——没有别的
    写者时这些工作全是白做，代价随日志长度线性增长。现在分三支：无新事实直接返回；本地仍是
    store 的前缀时只接尾部；前缀对不上或后端没有行级尾部读时退回整份重建。六颗分别钉：

    ① SQLite 读侧 `read_since` 在盘、按 `seq > ?` 只取尾部、且不重读整条历史（不调 `load_event_log`）；
    ② `RuntimeEventStore::read_since` 把 SQLite 委派下去，其余后端**显式**回落 `Ok(None)`；
    ③ `refresh_latest` 三支齐备（空尾部 no-op / 有尾部走 `apply_tail` / `None` 走 `rebuild_from_store`）；
    ④ `apply_tail` 用 P1-1 的 `append_batch` 接日志，且**不**整份重建索引；
    ⑤ 增量与整份重建共用同一个 `apply_index_event`（两份归约路径不能各写一份）；
    ⑥ 读侧前缀校验与归约侧增量路径各有一条行为用例在盘。
    """
    sqlite = case_source(SQLITE_BACKEND_FILE)
    pipeline = case_source(PIPELINE_FILE)
    read_since = _rust_fn_body(sqlite, "read_since")
    check(
        re.search(
            r"pub fn read_since\(\s*&self,\s*name: &str,\s*after_seq: Option<u64>,"
            r"\s*expected_prefix: Option<\(&Event, usize\)>,",
            sqlite,
        )
        is not None
        and read_since is not None
        and re.search(r"WHERE name = \?1 AND seq > \?2 ORDER BY position ASC", read_since)
        is not None
        and "load_event_log(" not in read_since,
        "SQLite 读侧 read_since 按 seq 只取尾部，且不重读整条历史",
        "read_since 不在盘" if read_since is None else "签名不符 / 没按 seq 过滤 / 仍调 load_event_log",
    )
    check(
        re.search(
            r"Self::Sqlite\(store\) => store\s*\.read_since\(name, after_seq, expected_prefix\)",
            pipeline,
        )
        is not None
        and re.search(r"_ => Ok\(None\)", pipeline) is not None,
        "RuntimeEventStore::read_since 委派 SQLite，其余后端显式回落 Ok(None)",
        "pipeline.rs 没把 read_since 委派给 SQLite，或缺少非 SQLite 后端的显式回落",
    )
    refresh = _rust_fn_body(pipeline, "refresh_latest")
    check(
        refresh is not None
        and "read_since(&self.log_name, after_seq, prefix)" in refresh
        and re.search(r"Some\(tail\) if tail\.is_empty\(\) => Ok\(\(\)\)", refresh) is not None
        and "self.apply_tail(&tail)" in refresh
        and "self.rebuild_from_store(false)" in refresh,
        "refresh_latest 三支齐备：空尾部 no-op / 有尾部增量 / 前缀不符整份重建",
        "refresh_latest 不在盘或分支不全",
    )
    apply_tail = _rust_fn_body(pipeline, "apply_tail")
    check(
        apply_tail is not None
        and "self.log.append_batch(tail)?" in apply_tail
        and "apply_index_event(event)?" in apply_tail
        and "rebuild_runtime_indexes(" not in apply_tail,
        "apply_tail 用 append_batch 接日志 + 逐条增量应用索引，不做整份重建",
        "apply_tail 不在盘，或没走 append_batch / 仍在整份重建索引",
    )
    rebuild_indexes = _rust_fn_body(pipeline, "rebuild_runtime_indexes")
    check(
        rebuild_indexes is not None
        and "apply_index_event(" in rebuild_indexes
        and apply_tail is not None
        and "apply_index_event(" in apply_tail,
        "增量与整份重建共用同一个 apply_index_event（归约单源）",
        "rebuild_runtime_indexes 与 apply_tail 没有共用 apply_index_event",
    )
    check(
        SQLITE_READ_SINCE_CASE in case_source(SQLITE_EVENT_LOG_TEST)
        and PIPELINE_CURSOR_CASE in pipeline,
        "游标增量：读侧前缀校验与归约侧增量路径各有一条行为用例在盘",
        f"缺 {SQLITE_EVENT_LOG_TEST}::{SQLITE_READ_SINCE_CASE} 或 {PIPELINE_FILE}::{PIPELINE_CURSOR_CASE}",
    )
    identity = case_source("crates/qx-runtime/src/pipeline/event_identity.rs")
    commit = case_source("crates/qx-runtime/src/pipeline/commit.rs")
    ingest = _rust_fn_body(commit, "ingest_commit")
    check(
        "event_identities: RuntimeEventIdentityIndex" in pipeline
        and "self.event_identities.remember(event)" in rebuild_indexes
        and "self.event_identities.remember(&event)" in _rust_fn_body(pipeline, "append_at_engine")
        and "self.event_identities.remember(event)" in apply_tail
        and ingest is not None
        and "self.event_identities.duplicate_ts(" in ingest
        and "self.log.events().iter().find(" not in ingest
        and all(
            name in identity
            for name in (
                "by_dedup_key",
                "by_correlation_source",
                "by_correlation",
                "min_by_key(|(seq, _)| *seq)",
                "duplicate_lookup_keeps_first_match_across_all_identity_paths",
            )
        ),
        "LiveEventPipeline 查重用追加/重放维护的身份索引，且保留最早命中语义",
        "查重索引未覆盖本地追加、尾部刷新、启动重放或最早命中行为",
    )


def valuation_single_source_check() -> None:
    """P1-6 / WP-19：三把权益/保证金尺子收敛成单一 `ValuationContext`/`ValuationResult`。

    收敛前同一个问题（「这账户值多少、还能用多少保证金」）有三处各自成立的算法：
    ① `Ledger` 的 `equity*` 家族（现货按乘数 / 衍生按合约规格 / 跨币种再叠 FX）——算术的正确
    落点，但**选了哪一把由调用方自己判断**；② `MarginState::equity`/`available` 的保证金口径；
    ③ 回测里按「有杠杆规格吗 / 有汇率吗」手工二选一的 `equity_for` 派发——同一段派发在
    `qx-xingban` 里**抄了两份**。六颗分别钉：

    ① `ValuationContext` / `ValuationResult` 在 `qx-core` 的 `valuation` 模块里，且 lib.rs
       既挂了模块又做了重导出（不然别的 crate 用不上）；
    ② raw `Ledger::valuate` 与 scale-aware `Ledger::valuate_exact` 分别持有唯一派发；
    ③ `MarginState::valuate` 在盘，且两个入口都经 `ValuationResult::new`（`available` 关系单源）；
    ④ 生产源码全文扫描：raw 与 exact 六把**参数化**尺子只能出现在 `ledger/query.rs`
       （定义点 + 两个唯一派发）——回测/CLI/报告里那几处手工派发必须消失。取 `production_text` 是为了剥掉注释与测试项：
       否则文档里提一句尺子名，或 `#[cfg(test)]` 用例里直接调原语，都会让「还有谁在直接派发」数不准；
    ⑤ `MarginState::equity` / `available` 委托 `valuate`（保证金算式不许在 `trading.rs` 里再写一份）；
    ⑥ raw/exact 派发均有逐值行为用例在盘；raw 汇率开/关两种尺子必须给出不同结果。

    刻意**不**纳入本颗的：`Ledger::equity_for`（乘数固定 1 的无参现货尺子）。它没有"选哪把"
    的歧义，`qx-cli` 的账户快照与策略上下文直接调它不构成第二处派发。
    """
    valuation = case_source(VALUATION_MODULE)
    check(
        (ROOT / VALUATION_MODULE).is_file()
        and "pub mod valuation;" in case_source("crates/qx-core/src/lib.rs")
        and all(
            name in case_source("crates/qx-core/src/lib.rs")
            for name in ("ExactValuationContext", "PaperValuationContext", "ValuationContext", "ValuationResult")
        ),
        "ValuationContext / ExactValuationContext / ValuationResult 落在 qx-core 的 valuation 模块，且 lib.rs 挂载并重导出",
        f"缺 {VALUATION_MODULE}，或 lib.rs 没挂模块 / 没重导出",
    )
    ledger_valuate = _rust_fn_body(case_source(EQUITY_RULER_DEFS), "valuate")
    check(
        ledger_valuate is not None
        and all(ruler in ledger_valuate for ruler in RAW_EQUITY_RULERS),
        "Ledger::valuate 在盘，且所有 raw 参数化权益尺子由它派发",
        "Ledger::valuate 不在盘，或它没有覆盖全部 raw 参数化权益尺子",
    )
    ledger_valuate_exact = _rust_fn_body(case_source(EQUITY_RULER_DEFS), "valuate_exact")
    check(
        ledger_valuate_exact is not None
        and all(ruler in ledger_valuate_exact for ruler in EXACT_EQUITY_RULERS),
        "Ledger::valuate_exact 在盘，且所有 scale-aware 权益尺子由它派发",
        "Ledger::valuate_exact 不在盘，或它没有覆盖全部 scale-aware 权益尺子",
    )
    check(
        re.search(
            r"pub fn valuate\(self, currency: impl Into<String>\) -> Option<ValuationResult>",
            valuation,
        )
        is not None
        and (valuation + case_source(EQUITY_RULER_DEFS)).count("ValuationResult::new(") >= 2,
        "MarginState::valuate 在盘，且两个入口共用 ValuationResult::new（available 关系单源）",
        "MarginState::valuate 不在盘，或两个入口没有共用 ValuationResult::new",
    )
    offenders: list[str] = []
    for path in rust_sources():
        rel = path.relative_to(ROOT).as_posix()
        if rel == EQUITY_RULER_DEFS:
            continue
        text = production_text(_read_text(path))
        if any(ruler in text for ruler in PARAMETERIZED_EQUITY_RULERS):
            offenders.append(rel)
    check(
        not offenders,
        "参数化权益尺子在生产源码里只出现在定义点与估值单点（其余一律走 Ledger::valuate）",
        f"这些文件仍在直接派发参数化尺子：{sorted(offenders)}",
    )
    trading = case_source("crates/qx-core/src/trading.rs")
    margin_equity = _rust_fn_body(trading, "equity")
    margin_available = _rust_fn_body(trading, "available")
    check(
        margin_equity is not None
        and "self.valuate(" in margin_equity
        and margin_available is not None
        and "self.valuate(" in margin_available,
        "MarginState::equity / available 委托 valuate（保证金算式不在 trading.rs 里再写一份）",
        "MarginState 的 equity/available 没有委托 valuate",
    )
    paper_case = re.sub(
        r"\s+", " ", case_source("crates/qx-app/src/cases/paper_available_margin_raw.rs")
    )
    paper_worker = re.sub(
        r"\s+", " ", case_source("crates/qx-service/src/paper_execution_host.rs")
    )
    paper_service = re.sub(
        r"\s+", " ", case_source("crates/qx-service/src/risk_host.rs")
    )
    single_bar = re.sub(r"\s+", " ", case_source("crates/qx-xingban/src/backtest.rs"))
    portfolio_bar = re.sub(
        r"\s+", " ", case_source("crates/qx-xingban/src/backtest/portfolio_session.rs")
    )
    check(
        (ROOT / VALUATION_CASE_FILE).is_file()
        and all(case in case_source(VALUATION_CASE_FILE) for case in VALUATION_DISPATCH_CASES)
        and ".valuate_paper(" in paper_case
        and "worker_risk_context(" in paper_worker
        and "pub fn worker_risk_context(" in paper_service
        and "paper_account_market_specs_and_fx(" in paper_service
        and "pub fn load_worker_spec_if_market_matches(" in paper_service
        and "required_fx.remove(&reporting_currency)" in paper_service
        and "qx_app::paper_available_margin_raw(" in paper_service
        and "strategy.refresh(&ledger, &account_id, &currency, derivative_spec.is_none())" in single_bar
        and "strategy.on_bar_orders_with_margin_exact_checked(" in portfolio_bar
        and ".saturating_sub(reserved)" in portfolio_bar
        and "Some(free_cash)" in portfolio_bar
        and "Some(free_cash_exact)" in portfolio_bar,
        "估值派发有四条行为用例在盘（valuate 与原始尺子逐值相等、有/无汇率给出不同的数）",
        f"缺 {VALUATION_CASE_FILE} 或估值派发用例不全；Paper 必须走含冻结规格/FX 的完整账户估值，"
        "单腿 Bar 只暴露现货结算现金、衍生保证金未认证时保持 None，多市场 Bar 使用扣除待计资金费后的现金预算",
    )
    ledger_types = case_source("crates/qx-core/src/ledger/mod.rs")
    ledger_fill = case_source("crates/qx-core/src/ledger/fill.rs")
    ledger_margin = _rust_fn_body(ledger_types, "apply_position_state_delta") or ""
    paper_valuation = _rust_fn_body(case_source(EQUITY_RULER_DEFS), "valuate_paper") or ""
    margin_projection = _rust_fn_body(case_source(EQUITY_RULER_DEFS), "position_initial_margin_raw") or ""
    leverage_case = case_source(VALUATION_CASE_FILE)
    check(
        re.search(r"pub leverage: Option<u32>", ledger_types) is not None
        and re.search(r"pub margin_ratio_raw: Option<i128>", ledger_types) is not None
        and "leverage: Some(policy.leverage)" in ledger_fill
        and "Some(weighted_ratio / next_abs)" in ledger_margin
        and "if next == 0" in ledger_margin
        and "initial_margin_for_market_specs_and_fx(" in paper_valuation
        and "margin_ratio_raw.ok_or_else" in margin_projection
        and "paper_valuation_uses_persisted_blended_position_leverage_and_fails_closed_when_unknown" in leverage_case
        and "缺少可回放的开仓杠杆" in leverage_case,
        "Paper 衍生持仓按可重放的开仓杠杆计初始保证金，未知旧杠杆 fail-closed",
        "缺少成交杠杆事实、加仓比例归并、平仓归零处理、Paper 保证金投影或未知杠杆行为用例",
    )
    orderbook_funding = case_source("crates/qx-xingban/src/orderbook_backtest/funding.rs")
    orderbook_projection = _rust_fn_body(orderbook_funding, "projected_margin_and_fees_raw") or ""
    check(
        "pub fn initial_margin_for_instrument(" in case_source(EQUITY_RULER_DEFS)
        and "margin_ratio_raw.ok_or_else" in case_source(EQUITY_RULER_DEFS)
        and "ledger.initial_margin_for_instrument(" in orderbook_projection
        and "derivative_margin_projection_uses_each_open_positions_persisted_leverage" in orderbook_funding
        and "derivative_margin_projection_refuses_a_legacy_position_without_leverage" in orderbook_funding,
        "OrderBook 已开仓衍生持仓按各自持久化杠杆投影，候选杠杆只用于新订单",
        "OrderBook 仍按候选杠杆重算当前仓位，或缺少已开仓杠杆/旧仓位拒绝行为用例",
    )
    event_source = case_source("crates/qx-core/src/event.rs")
    event_digest = _rust_fn_body(event_source, "digest") or ""
    check(
        "if let Some(leverage) = entry.leverage" in event_digest
        and "ledger_event_digest_includes_persisted_opening_leverage" in event_source,
        "EventLog 摘要纳入新开仓杠杆事实，同时保留旧缺字段事件的摘要兼容性",
        "账簿事件摘要未绑定杠杆事实，或缺少摘要差异行为用例",
    )


