def client_route_wiring_check() -> None:
    """C++ / Python 远端客户端的路由表 ⇔ qx-api 分派表逐一接线。

    九颗：① 两份声明面在盘；② 两份声明面非空（摘掉声明表就没有可核的东西）；③ 客户端声称的每个
    路由都在 qx-api 里存在（正向断链）；④ 两条腿逐条相等（同一契约的两种语言实现不得各说各话）；
    ⑤ qx-api 的每个 `/app/*` 入口都被客户端声明（反向：没有客户端能调的端点就是孤儿）；⑥ 每个路由
    字面量在客户端源码里只出现一次（声明表不是装饰——方法体里若另抄一份字面量，改一处就够让两处漂移）；
    ⑦ C++ 冒烟用例逐条覆盖声明表里的每个路由（声明了却没人跑过的路由是孤儿）；⑧ 声明面里每条路由都被
    客户端代码真的取用（只登记、不驱动请求的常量是装饰）；⑨ 客户端源码里没有声明面之外的 qx-api 路径
    字面量（方法体硬写一份 = 断链的另一面）。
    """
    api_routes = _api_declared_routes()
    tables: dict[str, list[str]] = {}
    missing_sources = [path for path, _ in CLIENT_ROUTE_TABLES.values() if not (ROOT / path).is_file()]
    check(
        not missing_sources,
        "远端客户端的路由声明面在盘（C++ 头文件 + Python 客户端）",
        f"缺 {missing_sources}",
    )
    if missing_sources:
        return
    for language, (path, declaration) in CLIENT_ROUTE_TABLES.items():
        tables[language] = _declared_client_routes(path, declaration, language)
    empty = [language for language, routes in tables.items() if not routes]
    check(
        not empty,
        "两份客户端路由声明面非空（声明表被摘掉就没有可核的东西）",
        f"空表 {empty}",
    )
    if empty:
        return

    dangling: list[str] = []
    for language, routes in tables.items():
        for route in routes:
            pattern = _route_pattern(route)
            if not any(pattern.match(candidate) for candidate in api_routes):
                dangling.append(f"{language}:{route}")
    check(
        not dangling,
        "客户端声称的每个路由都能在 qx-api 分派表里找到（前端调用一个后端不存在的端点当场红）",
        f"落空 {dangling}；分派表 {sorted(api_routes)}",
    )

    cpp_routes, python_routes = set(tables["cpp"]), set(tables["python"])
    check(
        cpp_routes == python_routes,
        "C++ 与 Python 远端客户端的路由表逐条相等（同一契约的两种语言实现不得各说各话）",
        f"仅 C++ 有 {sorted(cpp_routes - python_routes)} / 仅 Python 有 {sorted(python_routes - cpp_routes)}",
    )

    api_app_routes = sorted(route for route in api_routes if route.startswith("/app/"))
    orphan = [
        route
        for route in api_app_routes
        if not any(_route_pattern(route).match(declared) for declared in cpp_routes)
    ]
    check(
        bool(api_app_routes) and not orphan,
        "qx-api 的每个 /app/* 入口都被远端客户端声明（没有客户端能调的端点就是孤儿）",
        f"无人声明的入口 {orphan}；客户端声明 {sorted(cpp_routes)}",
    )

    duplicated: list[str] = []
    for language, (path, _declaration) in CLIENT_ROUTE_TABLES.items():
        text = (ROOT / path).read_text(encoding="utf-8")
        for route in sorted(set(tables[language])):
            occurrences = text.count('"' + route + '"')
            if occurrences != 1:
                duplicated.append(f"{language}:{route}x{occurrences}")
    check(
        not duplicated,
        "每个路由字面量在客户端源码里只有一处定义（方法体另抄一份字面量会让两处各自漂移）",
        f"重复定义 {duplicated}",
    )

    smoke_path = "cpp/tests/app_client_smoke.cpp"
    smoke = (ROOT / smoke_path).read_text(encoding="utf-8")
    smoke_routes = re.findall(r'"(/[^"]*)"', smoke)
    unexercised = [
        route
        for route in sorted(cpp_routes)
        if not any(
            _route_pattern(route).match(candidate.split("?", 1)[0])
            for candidate in smoke_routes
        )
    ]
    check(
        not unexercised,
        "C++ 冒烟用例逐条覆盖声明表里的每个路由（声明了却没人跑过的路由是孤儿）",
        f"没人跑过的路由 {unexercised}；冒烟用例 {sorted(set(smoke_routes))}",
    )

    # ⑧ 声明面里的每条路由都必须被客户端代码**真的取用**。只登记、不驱动请求的常量是装饰：
    #    C++ 侧曾把 `kRunStatusTemplate` / `kRunCancelTemplate` 列进 `kDeclaredRoutes`，真路径却由
    #    另一对 `kRunsPrefix` / `kRunCancelSuffix` 拼出来——门禁比的是模板（对的），请求发的是前缀
    #    （改坏了也不红），于是「声明表不是装饰」这句承诺恰好在 run_status / cancel_run 上落空。
    #    判据先把声明块与常量定义行都剥掉再找名字，所以「定义了但没人用」当场红。
    unconsumed: list[str] = []
    for language, (path, declaration) in CLIENT_ROUTE_TABLES.items():
        code = _client_code_only(path, language)
        match = re.search(declaration, code)
        if match is None:
            continue
        block = _balanced_brace_block(code, code.index("{", match.start()))
        outside = code.replace(block, "", 1)
        if language == "cpp":
            for ident in re.findall(r"[A-Za-z_][A-Za-z0-9_]*", block):
                definition = re.search(
                    r"inline constexpr std::string_view "
                    + re.escape(ident)
                    + r'\s*=\s*"[^"]*";',
                    outside,
                )
                if definition is None:
                    continue
                rest = outside.replace(definition.group(0), "", 1)
                if re.search(r"\b" + re.escape(ident) + r"\b", rest) is None:
                    unconsumed.append(f"cpp:{ident}")
        else:
            for key in re.findall(r'"([A-Za-z0-9_]+)"\s*:', block):
                if f'APP_ROUTE_TEMPLATES["{key}"]' not in outside:
                    unconsumed.append(f"python:{key}")
    check(
        not unconsumed,
        "声明面里每条路由都被客户端代码真的取用（只登记、不驱动请求的常量是装饰）",
        f"声明了却没人用 {unconsumed}",
    )

    # ⑨ 反向普查：客户端源码里不得出现声明面之外的 qx-api 路径字面量。方法体里硬写一份
    #    （`post("/app/backtst", ...)`）与漏登记是同一类断链的两个方向——只核「声明的都在服务端
    #    存在」会漏掉「发出去的请求根本不在声明面里」那一半。
    #    刻意只做「多出」这一向：声明面的字面量按构造就在源码里（C++ 的 `inline constexpr`
    #    定义、Python 的字典值），所以「声明的字面量在源码里找不到」这一向永远不可能为真，
    #    写上去只是给判据凑一个不可达的分支。
    stray: list[str] = []
    for language, (path, _declaration) in CLIENT_ROUTE_TABLES.items():
        literals = set(re.findall(r'"(/app/[^"]*)"', _client_code_only(path, language)))
        for extra in sorted(literals - set(tables[language])):
            stray.append(f"{language}:{extra}")
    check(
        not stray,
        "客户端源码里没有声明面之外的 qx-api 路径字面量（方法体硬写一份 = 断链的另一面）",
        f"声明面外多出 {stray}",
    )


# ---- C++ 最小消费者工程（方案 §6.3「最小消费者工程 / workspace 外消费」）----
#
# `cpp/tests/consumer/` 是方案 §6.3 点名的**下游独立工程**：它不 include 相对路径，而是
# `find_package(QianxingStrategySDK)` 消费 `cmake --install` 出来的导出 target，也就是
# 「下游独立工程从安装包消费」那条退出门的现场。此前门禁里 `grep tests/consumer` 零命中——
# 这份工程被删掉、CMake 退化成相对路径 include、或示例里另抄一份 qx-api 路径，门禁一条都不红。
# 示例代码尤其贵：使用者会照抄它，示例里硬写 `"/app/compare-runs"` 等于把「第二份声明面」
# 教给下游，而 header 里 `routes::kCompareRuns` 就摆在那儿。
CPP_CONSUMER_DIR = "cpp/tests/consumer"
CPP_CONSUMER_CMAKE = f"{CPP_CONSUMER_DIR}/CMakeLists.txt"
CPP_CONSUMER_MAIN = f"{CPP_CONSUMER_DIR}/main.cpp"


def cpp_consumer_example_check() -> None:
    """C++ 最小消费者工程：在盘、真消费导出 target、不另立路由声明面。

    三颗：① 工程两件在盘；② CMakeLists 走 `find_package` + `target_link_libraries` 消费导出
    target（不是相对路径 include 蹭进仓库——那样子工程仍在仓库里编译，测不出「workspace 外消费」）；
    ③ 示例源码取用 `qianxing::routes::` 声明面常量且不另抄 `/app/...` 字面量。
    """
    main_cpp = ROOT / CPP_CONSUMER_MAIN
    cmake = ROOT / CPP_CONSUMER_CMAKE
    missing = [str(p) for p in (main_cpp, cmake) if not p.is_file()]
    check(
        not missing,
        "C++ 最小消费者工程在盘（main.cpp + CMakeLists.txt）",
        f"缺 {missing}",
    )
    # 刻意不早退：这一族**恒发三条**。早退会让「文件被挪走」同时把总条数打下来，
    # 快照漂移判据跟着红——红出来的第二条会盖住第一条（而且「判据条数随盘上状态变」
    # 本身就是上一轮记过的坑）。缺文件时后两条按空文本判，自然落空。
    cmake_text = (
        re.sub(r"#[^\n]*", "", cmake.read_text(encoding="utf-8")) if cmake.is_file() else ""
    )
    consumes = (
        "find_package(QianxingStrategySDK" in cmake_text
        and "add_executable(" in cmake_text
        and "target_link_libraries(" in cmake_text
    )
    check(
        consumes,
        "消费者工程通过 find_package 消费导出 target（相对路径 include 测不出 workspace 外消费）",
        f"find_package={'find_package(QianxingStrategySDK' in cmake_text} "
        f"add_executable={'add_executable(' in cmake_text} "
        f"target_link_libraries={'target_link_libraries(' in cmake_text}",
    )
    code = _client_code_only(CPP_CONSUMER_MAIN, "cpp") if main_cpp.is_file() else ""
    literals = re.findall(r'"(/app/[^"]*)"', code)
    uses_table = re.search(r"qianxing::routes::k[A-Za-z0-9_]+", code) is not None
    check(
        not literals and uses_table,
        "消费者示例取用 routes 声明面而不是另抄一份 qx-api 路径（示例是使用者照抄的模板）",
        f"另抄的字面量 {literals}；取用声明面 {uses_table}",
    )


# ---- 跨语言二进制契约：QXRB 共享内存环布局（Rust / Python / C++ 三处手写镜像）----
#
# 环布局是**二进制**契约：三处各自手写常量，没有编译期耦合。Rust 侧创建文件、Python 与 C++
# 打开它；任一处偏移或魔数漂移，读出来的就是错位内存或 header mismatch，而门禁此前一条判据
# 都没核过（全仓 `grep QXRB tools/check_architecture.py` 零命中）。方案 §11 把「多语言契约
# 漂移」列为头号风险、缓解手段点名「字段级自动对照」，这里补上环布局那一格。
RING_LAYOUT_FILES = {
    "rust": "crates/qx-strategy/src/ring.rs",
    "python": "python/qianxing_strategy/ring.py",
    "cpp": "cpp/include/qianxing_ring.hpp",
}
RING_LAYOUT_FIELDS = (
    "MAGIC",
    "VERSION",
    "HEADER_BYTES",
    "SLOT_HEADER_BYTES",
    "WRITE_SEQ_OFFSET",
    "READ_SEQ_OFFSET",
    "SLOT_COMMIT_OFFSET",
    "SLOT_LEN_OFFSET",
    "SLOT_CRC_OFFSET",
)
# C++ 侧没有具名常量可读的地方：魔数比较、header 四个字段、seq 与 slot 偏移按子串指纹逐条对齐。
RING_CPP_ANCHORS = (
    'std::memcmp(mapping_.data(), "QXRB", 4)',
    "load_u32(4) != 1",
    "load_u32(8) != slot_bytes",
    "load_u32(12) != capacity",
    "load_u64(16)",
    "load_u64(24)",
    "store_u32(slot + 8,",
    "store_u32(slot + 12,",
)


def _ring_value(raw: str) -> str:
    value = raw.strip().rstrip(";").strip()
    for prefix in ("*b", "b"):
        if value.startswith(prefix):
            value = value[len(prefix) :]
    return value.strip().strip('"')


def _ring_layout(text: str, language: str) -> dict[str, str]:
    layout: dict[str, str] = {}
    for field in RING_LAYOUT_FIELDS:
        if language == "rust":
            match = re.search(rf"const {field}: [^=\n]+= ([^;\n]+);", text)
        else:
            match = re.search(rf"^{field} = ([^\n]+)$", text, re.M)
        if match is not None:
            layout[field] = _ring_value(match.group(1))
    return layout


def ring_layout_cross_language_check() -> None:
    """QXRB 共享内存环布局在 Rust / Python / C++ 三处手写镜像之间逐格一致。

    六颗：① 三处实现在盘；② Rust 与 Python 的九格布局常量都取得到；③ 两者逐格相等；
    ④ C++ 的 kHeaderBytes / kSlotHeaderBytes 等于 Rust 的 HEADER_BYTES / SLOT_HEADER_BYTES；
    ⑤ C++ 头文件的魔数与 header/seq/slot 偏移逐条对齐 Rust（子串指纹）；⑥ 环布局有跨语言
    运行时用例在盘（常量被真的跑过，不只是声明）。
    """
    missing = [path for path in RING_LAYOUT_FILES.values() if not (ROOT / path).is_file()]
    check(not missing, "QXRB 环布局的三处实现在盘（Rust / Python / C++）", f"缺 {missing}")
    if missing:
        return
    rust = _ring_layout((ROOT / RING_LAYOUT_FILES["rust"]).read_text(encoding="utf-8"), "rust")
    python = _ring_layout((ROOT / RING_LAYOUT_FILES["python"]).read_text(encoding="utf-8"), "python")
    check(
        set(rust) == set(RING_LAYOUT_FIELDS) and set(python) == set(RING_LAYOUT_FIELDS),
        "Rust 与 Python 的九格环布局常量都能取到（缺一格就少一份核对）",
        f"rust 缺 {sorted(set(RING_LAYOUT_FIELDS) - set(rust))} / "
        f"python 缺 {sorted(set(RING_LAYOUT_FIELDS) - set(python))}",
    )
    drift = [field for field in RING_LAYOUT_FIELDS if rust.get(field) != python.get(field)]
    check(
        not drift,
        "Rust 与 Python 的环布局九格逐格相等（同一份二进制契约的两种语言镜像）",
        f"漂移 {[(field, rust.get(field), python.get(field)) for field in drift]}",
    )
    cpp = (ROOT / RING_LAYOUT_FILES["cpp"]).read_text(encoding="utf-8")
    cpp_header = re.search(r"kHeaderBytes = (\d+)", cpp)
    cpp_slot = re.search(r"kSlotHeaderBytes = (\d+)", cpp)
    check(
        cpp_header is not None
        and cpp_slot is not None
        and cpp_header.group(1) == rust.get("HEADER_BYTES")
        and cpp_slot.group(1) == rust.get("SLOT_HEADER_BYTES"),
        "C++ 的 kHeaderBytes / kSlotHeaderBytes 等于 Rust 的 HEADER_BYTES / SLOT_HEADER_BYTES",
        f"C++ {cpp_header and cpp_header.group(1)}/{cpp_slot and cpp_slot.group(1)} "
        f"vs Rust {rust.get('HEADER_BYTES')}/{rust.get('SLOT_HEADER_BYTES')}",
    )
    absent = [anchor for anchor in RING_CPP_ANCHORS if anchor not in cpp]
    check(
        not absent,
        "C++ 头文件的魔数与 header/seq/slot 偏移逐条对齐 Rust（子串指纹）",
        f"缺失 {absent}",
    )
    witness = ROOT / "crates/qx-cli/tests/unit/strategy_worker_entries.rs"
    witness_text = witness.read_text(encoding="utf-8") if witness.is_file() else ""
    check(
        "shared_memory_json" in witness_text
        and "--input-ring" in witness_text
        and '"cpp"' in witness_text,
        "环布局有跨语言运行时用例在盘（Rust/Python/C++ 三侧的共享 ring 实参都被真的构造过）",
        f"证据文件 {witness} 在盘 {witness.is_file()}",
    )


# ---- 语言/API 契约映射表（方案 §2 的基线复核产物；§8「跨语言同一 Run」的登记面）----
#
# `maturity/app_use_cases.yaml` 已经把用例与 Rust 的 `cases/` 目录、`pub use`、九项文档表对上了，
# 但**一个字都没提另外三种语言面**。方案 §2 点名「语言/API 契约映射表」是基线复核产物，§8 又要求
# 「跨语言同一 Run」——两句话指向同一件事：11 个用例在 Rust 用例本体 / Python 进程内扩展 /
# Python 远端 HTTP 门面 / C++ 远端 HTTP 门面里必须**逐一对应**。此前新增一个用例时，Rust 侧三处
# 齐全、门禁全绿，两条远端门面却可以静默地少一个入口，集成方要到运行时才知道「这个方法不存在」。
# 它与「语言腿多出一个没人认领的入口」是同一类孤儿的两面，所以正反两侧都要核。
LANGUAGE_CONTRACT_FILE = "maturity/language_api_contract.yaml"
LANGUAGE_CONTRACT_KIND = "language-api-contract"
LANGUAGE_CONTRACT_LANGUAGES = ("rust", "python_native", "python_remote", "cpp_remote", "http")
PYTHON_APP_MODULE = "python/qianxing/app.py"
PYTHON_REMOTE_CLASSES = ("AppClient", "TradeWorkflowClient")
CPP_APP_HEADER = "cpp/include/qianxing_app.hpp"


def _text_or_empty(path: "Path") -> str:
    """缺文件时返回空串：这一族**恒发九条**，不能让一次缺文件把总条数打下来（快照漂移会盖住真红）。"""
    return _read_text(path) if path.is_file() else ""


def _language_contract_rows() -> list[dict[str, object]]:
    """解析映射表的 `contracts:` 段（逐行，不引 yaml 依赖）。"""
    rows: list[dict[str, object]] = []
    current: dict[str, object] | None = None
    inside = False
    for line in _text_or_empty(ROOT / LANGUAGE_CONTRACT_FILE).splitlines():
        if re.match(r"^contracts:\s*$", line):
            inside, current = True, None
            continue
        if re.match(r"^\S", line):
            inside, current = False, None
            continue
        if not inside:
            continue
        if matched := re.match(r"^  - use_case:\s*(\S+)\s*$", line):
            current = {"use_case": matched.group(1)}
            rows.append(current)
        elif current is not None and (
            matched := re.match(r"^    ([a-z_]+):\s*\[(.*)\]\s*$", line)
        ):
            current[matched.group(1)] = [
                item.strip().strip('"') for item in matched.group(2).split(",") if item.strip()
            ]
    return rows


def _named_roster(section: str) -> set[str]:
    """读映射表里 `section:` 下的 `- name: X` 名册（生命周期 / 自检 helper 的显式名单）。"""
    names: set[str] = set()
    inside = False
    for line in _text_or_empty(ROOT / LANGUAGE_CONTRACT_FILE).splitlines():
        if re.match(rf"^{re.escape(section)}:\s*$", line):
            inside = True
            continue
        if re.match(r"^\S", line):
            inside = False
            continue
        if inside and (matched := re.match(r"^  - name:\s*(\S+)\s*$", line)):
            names.add(matched.group(1))
    return names


def _python_native_functions() -> list[str]:
    """进程内 Rust 门面公开入口：app 自由函数与已登记的本地 ProviderRegistry 用例。"""
    app_functions = [
        name
        for name in re.findall(
            r"^def ([A-Za-z_][A-Za-z0-9_]*)\(", _text_or_empty(ROOT / PYTHON_APP_MODULE), re.MULTILINE
        )
        if not name.startswith("_")
    ]
    provider_text = _text_or_empty(ROOT / "python/qianxing/data/providers.py")
    provider_block = provider_text.partition("class ProviderRegistry:")[2].split("\nclass ", 1)[0]
    provider_methods = [
        f"ProviderRegistry.{method}"
        for method in ("run_backtest_with_manifest", "run_depth_backtest")
        if re.search(rf"^    def {method}\(", provider_block, re.MULTILINE)
    ]
    return app_functions + provider_methods


def _python_class_lines(class_name: str) -> list[str]:
    """某个类的类体行（从 `class X(` 之后到下一个顶层语句之前）。"""
    text = _text_or_empty(ROOT / PYTHON_APP_MODULE)
    marker = f"class {class_name}("
    if marker not in text:
        return []
    body: list[str] = []
    for line in text[text.index(marker) :].splitlines()[1:]:
        if line and not line[0].isspace():
            break
        body.append(line)
    return body


def _python_public_methods(class_name: str) -> list[str]:
    """某个远端门面类的公开方法（下划线开头的是传输 / 构造 helper，不算门面）。"""
    return [
        name
        for name in re.findall(
            r"^    def ([A-Za-z_][A-Za-z0-9_]*)\(",
            "\n".join(_python_class_lines(class_name)),
            re.MULTILINE,
        )
        if not name.startswith("_")
    ]


def _cpp_public_methods() -> list[str]:
    """`AppClient` 的公开方法（`private:` 之后的 run_path / get / post 是传输 helper）。"""
    text = _text_or_empty(ROOT / CPP_APP_HEADER)
    marker = "class AppClient {"
    if marker not in text:
        return []
    block = _balanced_brace_block(text, text.index("{", text.index(marker)))
    return re.findall(
        r"AppResponse\s+([A-Za-z_][A-Za-z0-9_]*)\s*\(", block.split("private:", 1)[0]
    )


def language_api_contract_check() -> None:
    """方案 §2 的「语言/API 契约映射表」：11 个用例在五种语言面里逐一对应。

    九颗：① 映射表在盘、自述 kind 正确、每个用例五种语言面齐格且用例名不重复；② 用例集合 ==
    `maturity/app_use_cases.yaml` 的用例集合（两张登记面不得各说各话）；③ 每格点名的 Rust
    `pub fn` 真的在 `cases/<use_case>.rs` 里；④ 每格点名的 Python 入口在盘（`python_native` 看
    模块级 `def` 或显式登记的 ProviderRegistry 用例，`python_remote` 看 `AppClient` / `TradeWorkflowClient` 的公开方法）；⑤ 每格点名的
    C++ 方法在 `AppClient` 的公开面里；⑥ 每格点名的 `http` 路由都在两张客户端路由声明面里
    （用例 → 路由 → 声明面，三段接得上）；⑦⑧⑨ 反向普查三条腿——客户端公开面里没有未被任何用例
    认领的入口（除了显式名册里的生命周期 / 自检 helper）。刻意不早退：这一族恒发九条。
    """
    text = _text_or_empty(ROOT / LANGUAGE_CONTRACT_FILE)
    declared_kind = re.search(r"^kind:\s*(\S+)\s*$", text, re.MULTILINE)
    rows = _language_contract_rows()
    names = [str(row.get("use_case", "")) for row in rows]
    incomplete = [
        name
        for row, name in zip(rows, names)
        if any(key not in row for key in LANGUAGE_CONTRACT_LANGUAGES)
    ]
    check(
        declared_kind is not None
        and declared_kind.group(1) == LANGUAGE_CONTRACT_KIND
        and bool(rows)
        and len(names) == len(set(names))
        and not incomplete,
        "语言/API 契约映射表在盘、自述 kind 正确、每个用例五种语言面齐格且用例名不重复",
        f"kind {declared_kind.group(1) if declared_kind else '缺'}；"
        f"用例 {len(names)} 个（去重 {len(set(names))}）；缺格 {incomplete or '无'}",
    )

    registered = [entry.get("name", "") for entry in _app_use_case_registry()]
    check(
        bool(registered) and set(names) == set(registered),
        "映射表的用例集合 == `maturity/app_use_cases.yaml` 的用例集合（两张登记面不得各说各话）",
        f"映射表独有 {sorted(set(names) - set(registered))}；"
        f"用例登记面独有 {sorted(set(registered) - set(names))}",
    )

    rust_client_source = "\n".join(
        _read_text(path)
        for path in sorted((ROOT / "crates/qx-sdk/src/client").rglob("*.rs"))
    ) + "\n" + _text_or_empty(ROOT / "crates/qx-sdk/src/client.rs")
    missing_rust = [
        f"{row['use_case']}:{entry}"
        for row in rows
        for entry in row.get("rust", [])
        if not (
            f"pub fn {entry}("
            in _text_or_empty(ROOT / APP_CASES_DIR / f"{row['use_case']}.rs")
            if not entry.startswith("Client.")
            else (
                f"pub fn {entry.removeprefix('Client.')}(" in rust_client_source
                or f"pub fn {entry.removeprefix('Client.')}<" in rust_client_source
            )
        )
    ]
    check(
        not missing_rust,
        "映射表点名的每个 Rust 入口都是 `cases/<use_case>.rs` 里的 `pub fn`（Rust 腿也有牙齿）",
        f"落空 {missing_rust}",
    )

    native_functions = set(_python_native_functions())
    remote_methods = {
        method
        for class_name in PYTHON_REMOTE_CLASSES
        for method in _python_public_methods(class_name)
    }
    provider_text = _text_or_empty(ROOT / "python/qianxing/data/providers.py")
    provider_block = provider_text.partition("class ProviderRegistry:")[2].split("\nclass ", 1)[0]
    provider_method_names = re.findall(
        r"^    def ([A-Za-z_][A-Za-z0-9_]*)\(", provider_block, re.MULTILINE
    )
    duplicate_provider_methods = sorted(
        name for name in set(provider_method_names) if provider_method_names.count(name) > 1
    )
    missing_python = [
        f"{row['use_case']}:native:{entry}"
        for row in rows
        for entry in row.get("python_native", [])
        if entry not in native_functions
    ] + [
        f"{row['use_case']}:remote:{entry}"
        for row in rows
        for entry in row.get("python_remote", [])
        if entry not in remote_methods
    ]
    check(
        not missing_python and not duplicate_provider_methods,
        "映射表点名的每个 Python 入口都在盘（进程内扩展看模块级 `def`，远端门面看公开方法）",
        f"入口落空 {missing_python}；ProviderRegistry 重复定义 {duplicate_provider_methods}",
    )

    cpp_methods = set(_cpp_public_methods())
    missing_cpp = [
        f"{row['use_case']}:{entry}"
        for row in rows
        for entry in row.get("cpp_remote", [])
        if entry not in cpp_methods
    ]
    check(
        not missing_cpp,
        "映射表点名的每个 C++ 入口都是 `AppClient` 的公开方法（C++ 腿也有牙齿）",
        f"落空 {missing_cpp}；AppClient 公开面 {sorted(cpp_methods)}",
    )

    client_routes: set[str] = set()
    for language, (path, declaration) in CLIENT_ROUTE_TABLES.items():
        client_routes.update(_declared_client_routes(path, declaration, language))
    missing_http = [
        f"{row['use_case']}:{route}"
        for row in rows
        for route in row.get("http", [])
        if route not in client_routes
    ]
    check(
        not missing_http,
        "映射表点名的每条路由都在客户端路由声明面里（用例 → 路由 → 声明面三段接得上）",
        f"落空 {missing_http}；声明面 {sorted(client_routes)}",
    )

    declared_native = {entry for row in rows for entry in row.get("python_native", [])}
    native_helpers = _named_roster("python_native_helpers")
    check(
        not (native_functions - declared_native - native_helpers),
        "进程内扩展的公开函数都被某个用例认领（多出一个没人认领的入口 = 孤儿逻辑的另一面）",
        f"未认领 {sorted(native_functions - declared_native - native_helpers)}；"
        f"helper 名册 {sorted(native_helpers)}",
    )

    declared_remote = {entry for row in rows for entry in row.get("python_remote", [])}
    remote_lifecycle = _named_roster("python_remote_lifecycle_methods")
    remote_helpers = _named_roster("python_remote_helpers")
    check(
        not (remote_methods - declared_remote - remote_lifecycle - remote_helpers),
        "Python 远端门面的公开方法都被用例或显式生命周期名册认领",
        f"未认领 {sorted(remote_methods - declared_remote - remote_lifecycle - remote_helpers)}；"
        f"映射表 {sorted(declared_remote)}；生命周期名册 {sorted(remote_lifecycle)}",
    )

    declared_cpp = {entry for row in rows for entry in row.get("cpp_remote", [])}
    lifecycle = _named_roster("cpp_lifecycle_methods")
    cpp_helpers = _named_roster("cpp_remote_helpers")
    check(
        not (cpp_methods - declared_cpp - lifecycle - cpp_helpers),
        "C++ `AppClient` 的公开方法都被某个用例认领（或落在显式的 run 生命周期名册里）",
        f"未认领 {sorted(cpp_methods - declared_cpp - lifecycle - cpp_helpers)}；"
        f"生命周期名册 {sorted(lifecycle)}；辅助读入口 {sorted(cpp_helpers)}",
    )

    rust_remote = _named_roster("rust_remote_lifecycle_methods")
    rust_remote_source = _text_or_empty(ROOT / "crates/qx-sdk/src/remote.rs")
    rust_remote_methods = set(
        re.findall(r"pub fn ([A-Za-z_][A-Za-z0-9_]*)\s*\(", rust_remote_source)
    )
    check(
        rust_remote <= rust_remote_methods,
        "Rust 远端生命周期名册中的方法都由 qx-sdk 公开实现",
        f"缺失 {sorted(rust_remote - rust_remote_methods)}；已实现 {sorted(rust_remote_methods)}",
    )


# ---- 等待默认有限（方案 §9「无死循环、孤儿逻辑和资源治理」）----
#
# 方案 §9 的原话是「`wait()` 默认有限时；无限等待仅由调用方显式请求并可取消」。这条纪律此前
# 一条判据都没有：同一个 SDK 的两条腿对"等多久"给了两个相反的答案——远端句柄
# `RemoteRunHandle.wait` 的缺省是 30 s，原生句柄 `RunHandle.wait` 的缺省是 `None`，一路透到
# `qx-python` 的 `loop { … }` 上就是**一直等**；`qx-app::RunHandle::wait()` 更是连超时参数都没有，
# 直接 `receiver.recv()` 堵到底。调用方一个参数都不写就拿到了无限等待，而且拿不到"最多等多久"
# 这个选项。五颗分别钉常量、两条腿的缺省、Rust 侧的路由、超时支的语义与行为用例。
WAIT_DEFAULT_PY = "python/qianxing/app.py"
WAIT_DEFAULT_RS = "crates/qx-app/src/run_handle.rs"
WAIT_DEFAULT_CEILING_SECONDS = 60


def bounded_wait_default_check() -> None:
    """方案 §9：`wait()` 默认有限；无限等待只能由调用方显式请求。

    五颗：① 两条腿的有限缺省常量都在盘且是有限正值（Python `DEFAULT_RUN_WAIT_MS`、
    Rust `DEFAULT_WAIT_TIMEOUT`），且 Rust 那个不超过 [`WAIT_DEFAULT_CEILING_SECONDS`]——"有限"
    不能靠把常量写成十年；② Python 两条腿的 `wait` 缺省都不是 `None`；③ Rust `wait()` 走那个
    有限缺省（体里引用 `DEFAULT_WAIT_TIMEOUT`）而不是裸 `recv()`；④ 有界等待用 `recv_timeout`，
    且**超时单独一支且不置 FAILED**（到点没结果 = "还没好"，不是"坏了"；把超时并进断连那一支会
    让一次正常到点把还在跑的运行记成失败）；⑤ 有界等待有行为用例在盘（Rust 侧断言到点返回当前
    状态而不是 Failed，Python 侧断言两条腿的缺省都不是 None）。
    """
    python_text = _text_or_empty(ROOT / WAIT_DEFAULT_PY)
    rust_text = _text_or_empty(ROOT / WAIT_DEFAULT_RS)
    python_ms = re.search(r"^DEFAULT_RUN_WAIT_MS = ([\d_]+)\s*$", python_text, re.MULTILINE)
    rust_secs = re.search(
        r"^pub const DEFAULT_WAIT_TIMEOUT: Duration = Duration::from_secs\((\d+)\);",
        rust_text,
        re.MULTILINE,
    )
    check(
        python_ms is not None
        and int(python_ms.group(1).replace("_", "")) > 0
        and rust_secs is not None
        and 0 < int(rust_secs.group(1)) <= WAIT_DEFAULT_CEILING_SECONDS,
        "两条腿的等待缺省都是有限正值（Python 毫秒常量 + Rust `Duration::from_secs`，且不超上限）",
        f"python={python_ms and python_ms.group(1)}；rust={rust_secs and rust_secs.group(1)} "
        f"（上限 {WAIT_DEFAULT_CEILING_SECONDS} s）",
    )

    unbounded: list[str] = []
    for class_name in ("RunHandle", "RemoteRunHandle"):
        body = "\n".join(_python_class_lines(class_name))
        matched = re.search(
            r"^    def wait\(self, (timeout[_a-z]*): [^=]+= ([^,)]+)[,)]", body, re.MULTILINE
        )
        if matched is None:
            unbounded.append(f"{class_name}:没有可读的 wait 缺省")
        # 比的是 group(2)（缺省值），不是 group(1)（参数名）——第一版写成 group(1)，
        # 于是这条判据永远不红（把缺省改回 None 时它照印全绿），由变异脚本当场抓出来。
        elif matched.group(2).strip() == "None":
            unbounded.append(f"{class_name}:缺省是 None（= 一直等）")
    check(
        not unbounded,
        "Python 两条腿的 `wait` 缺省都不是 `None`（无限等待必须由调用方写出来）",
        f"问题 {unbounded}",
    )

    wait_body = re.search(r"pub fn wait\(&mut self\) -> RunStatus \{\n([\s\S]*?)\n    \}", rust_text)
    routes = wait_body is not None and "DEFAULT_WAIT_TIMEOUT" in wait_body.group(1)
    check(
        routes and "receiver.recv()" not in wait_body.group(1),
        "Rust `wait()` 走有限缺省常量而不是裸 `receiver.recv()`（无参 `wait` 不得无界阻塞）",
        f"体里引用 DEFAULT_WAIT_TIMEOUT={routes}",
    )

    timeout_arm = re.search(
        r"Ok\(Err\(RecvTimeoutError::Timeout\)\)\s*=>\s*\{\s*\}", rust_text
    )
    check(
        "recv_timeout(" in rust_text and timeout_arm is not None,
        "有界等待用 `recv_timeout`，且超时单独一支且不置 FAILED（到点不是坏了）",
        f"recv_timeout={'recv_timeout(' in rust_text}；空超时臂={timeout_arm is not None}",
    )

    rust_witness = "fn a_deadline_return_reports_the_current_state_instead_of_failing_the_run("
    python_witness = "def test_both_run_handles_default_to_a_finite_wait("
    python_tests = _text_or_empty(ROOT / "python/tests/test_app_use_cases.py")
    check(
        rust_witness in rust_text and python_witness in python_tests,
        "有界等待有行为用例在盘（Rust 到点返回当前状态 + Python 两条腿缺省有限）",
        f"rust={rust_witness in rust_text}；python={python_witness in python_tests}",
    )


