def _parse_named_records(path: "Path", wanted: tuple[str, ...]) -> dict[str, list[dict[str, object]]]:
    """把「`段:` 下若干 `- name: X` 记录」的 YAML 登记面解析成 `{段名: [记录]}`。

    记录体只认两种行：`    key: [a, b]`（方括号列表）与 `    key: value`（标量）。
    门禁不引 PyYAML，所以这段逐行读法被两张登记面（能力矩阵、主链路调用图）共用——
    **只此一份**：复制第二份会让「改了解析口径只改一处」变成一次静默漂移。
    """
    sections: dict[str, list[dict[str, object]]] = {name: [] for name in wanted}
    current_section: str | None = None
    current: dict[str, object] | None = None
    for line in _text_or_empty(path).splitlines():
        if matched := re.match(rf"^({'|'.join(wanted)}):\s*$", line):
            current_section, current = matched.group(1), None
            continue
        if re.match(r"^[A-Za-z_]+:", line):  # 下一个顶层键结束本段
            current_section, current = None, None
            continue
        if current_section is None:
            continue
        if matched := re.match(r"^  - name:\s*(\S+)\s*$", line):
            current = {"name": matched.group(1)}
            sections[current_section].append(current)
            continue
        if current is None:
            continue
        if matched := re.match(r"^    ([a-z_]+):\s*\[(.*)\]\s*$", line):
            current[matched.group(1)] = [
                item.strip().strip('"') for item in matched.group(2).split(",") if item.strip()
            ]
        elif matched := re.match(r'^    ([a-z_]+):\s*"?(.*?)"?\s*$', line):
            current[matched.group(1)] = matched.group(2)
    return sections


def _matrix_roster(section: str) -> list[str]:
    """读 `section:` 下的 `- 名字` 名册（levels / capability_fields / provider_fields）。"""
    names: list[str] = []
    inside = False
    for line in _text_or_empty(ROOT / CAPABILITY_MATRIX_FILE).splitlines():
        if re.match(rf"^{re.escape(section)}:\s*$", line):
            inside = True
            continue
        if re.match(r"^\S", line):
            inside = False
            continue
        if inside and (matched := re.match(r"^  - (\S+)\s*$", line)):
            names.append(matched.group(1))
    return names


def _maturity_capability_roster() -> set[str]:
    """Read the stable capability keys under the internal evidence register."""
    lines = _text_or_empty(ROOT / "maturity/capabilities.yaml").splitlines()
    try:
        start = lines.index("capabilities:") + 1
    except ValueError:
        return set()
    names: set[str] = set()
    for line in lines[start:]:
        if line and not line[0].isspace():
            break
        if matched := re.fullmatch(r"  ([a-z][a-z0-9_]*):", line):
            names.add(matched.group(1))
    return names


def _production_trait_impls() -> dict[str, dict[str, str]]:
    """生产代码里 `impl <trait> for X` 的落点：trait 名 -> {类型名: 文件}。

    只认**行首顶格**的 `impl`：写在 `mod tests` 里的替身是缩进的，天然不算——测试替身不该被当成
    一个真实 venue/provider 去评档（`crates/qx-data/src/batch.rs` 与 `qx-provider` 的 `MockProvider`
    都正是那种形状）。一次扫描同时收两个 trait，免得为两颗判据各走一遍全仓。
    """
    wanted = ("Venue", "DataProvider")
    found: dict[str, dict[str, str]] = {trait: {} for trait in wanted}
    for path in sorted((ROOT / "crates").rglob("*.rs")):
        relative = path.relative_to(ROOT).as_posix()
        if TEST_PATH.search(relative):
            continue
        text = production_text(_read_text(path))
        for trait in wanted:
            for matched in re.finditer(rf"^impl {trait} for (\w+)", text, re.MULTILINE):
                found[trait][matched.group(1)] = relative
    return found


def _boolean_capability_flags(text: str) -> list[str]:
    """找出把能力写成布尔值的地方（`supported: true` 那一类）。

    方案 §2 的硬要求是「不得用布尔值 `supported=true` 掩盖限制」。判据要能自证，所以做成纯函数
    并自带反例——一条从不发声的空判据靠不住。
    """
    offenders: list[str] = []
    for line in text.splitlines():
        matched = re.match(r"^\s+(?:-\s+)?([a-z_]+):\s*(true|false|True|False)\s*$", line)
        if matched:
            offenders.append(f"{matched.group(1)}={matched.group(2)}")
    return offenders


# —— 能力执行记录：把"能不能真的跑起来"变成一份可复核的观测（V13 R27）——

CAPABILITY_EXECUTION_FILE = "maturity/capability_execution.yaml"
CAPABILITY_EXECUTION_PROBE = "tools/capability_execution_probe.py"
CAPABILITY_EXECUTION_VERDICTS = ("executed", "delegated", "blocked")


def _probe_subcommand_tokens(command: str) -> list[str]:
    """从 `qx-cli <子命令> <参数…>` 里取出子命令词。

    取到第一个「像路径（含 `/` 或以 `.json` 结尾）或像旗标（`--` 开头）」的词为止——那些在
    生成器里是常量（`BAR_PRIMARY` 之类），拿字面量去比对只会得到假红。子命令词则必须逐字
    出现在生成器里，否则这条 `executed` 就没有跑它的代码。
    """
    tokens = command.split()
    if tokens and tokens[0] == "qx-cli":
        tokens = tokens[1:]
    subcommand: list[str] = []
    for token in tokens:
        if token.startswith("--") or "/" in token or token.endswith(".json"):
            break
        subcommand.append(token)
    return subcommand


def capability_execution_check() -> None:
    """能力执行记录：真的跑过、跑出数、以及**没有**跑的那些卡在哪（V13 R27）。

    用户最直接的问题是「这些核心能力到底能不能全部执行」。能力矩阵回答"走到哪一档"、能力阶梯
    回答"子系统在四档上的位置"、主链路调用图回答"每一段锚在哪个符号上"——三者都不回答
    "把命令敲下去会发生什么"。本族守的就是那份观测记录：

    ① 记录在盘、自述 kind/schema_version/generated_by 齐全、能力名册非空；
    ② 生成器在盘，且每条 `executed` 的子命令词真在生成器里（记录是**跑出来**的，不是手写的）；
    ③ 每条能力的 `anchor` 在盘（能力不许锚在不存在的落点上）；
    ④ 判定落在闭集里；`blocked` 必须写明卡在哪条前置上；`delegated` 必须指向在盘的记录
       ——"没跑"和"跑不了"是两件事，前者必须给出前置条件，后者必须给出真正的观测；
    ⑤ 每条 `executed` 都记了**带数字**的观测值（跑出 0 笔成交的"通过"是空跑）；
    ⑥ 能力名唯一，且每条 evidence 路径都在盘。

    **恒发六颗、不早退**。刻意不在这里重跑探针：探针要编译产物、要几分钟，门禁只核"记录与
    生成器自洽且证据在盘"——真跑由 `tools/capability_execution_probe.py` 负责，这也是本仓
    `paper_acceptance` / `backtest_acceptance` 两条轨的同一口径。
    """
    path = ROOT / CAPABILITY_EXECUTION_FILE
    text = _text_or_empty(path)
    probe_src = _text_or_empty(ROOT / CAPABILITY_EXECUTION_PROBE)
    records = _parse_named_records(path, ("capabilities",)).get("capabilities", [])
    executed = [record for record in records if record.get("verdict") == "executed"]

    # ① 记录在盘、自述齐全、名册非空。
    check(
        bool(text)
        and re.search(r"^kind:\s*capability-execution\s*$", text, re.MULTILINE) is not None
        and re.search(r"^schema_version:\s*1\s*$", text, re.MULTILINE) is not None
        and "generated_by:" in text
        and bool(records),
        "能力执行记录在盘、自述 kind/schema_version/generated_by 齐全、能力名册非空",
        f"记录 {'有' if text else '缺'} / 能力 {len(records)} 条",
    )

    # ② 每条 executed 的子命令词真在生成器里。
    undeclared = [
        str(record.get("name"))
        for record in executed
        if not all(
            f'"{token}"' in probe_src
            for token in _probe_subcommand_tokens(str(record.get("command", "")))
        )
    ]
    check(
        bool(probe_src) and bool(executed) and not undeclared,
        "每条 executed 能力的子命令都真在生成器脚本里（记录是跑出来的，不是手写的）",
        f"生成器 {'有' if probe_src else '缺'} / executed {len(executed)} 条 / 未声明 {undeclared or '无'}",
    )

    # ③ 每条能力的 anchor 在盘。
    missing_anchor = [
        str(record.get("name"))
        for record in records
        if not (ROOT / str(record.get("anchor", ""))).exists()
    ]
    check(
        not missing_anchor,
        "每条能力的 anchor 路径都在盘（能力不许锚在不存在的落点上）",
        f"锚点缺失 {missing_anchor or '无'}",
    )

    # ④ 判定闭集 + blocked 写明前置 + delegated 指向在盘记录。
    bad_verdict = [
        str(record.get("name"))
        for record in records
        if record.get("verdict") not in CAPABILITY_EXECUTION_VERDICTS
    ]
    blocked_empty = [
        str(record.get("name"))
        for record in records
        if record.get("verdict") == "blocked" and not str(record.get("blocked_by", "")).strip()
    ]
    delegated_broken = [
        str(record.get("name"))
        for record in records
        if record.get("verdict") == "delegated"
        and not (ROOT / str(record.get("delegated_to", ""))).exists()
    ]
    check(
        not bad_verdict and not blocked_empty and not delegated_broken,
        "判定落在闭集里；blocked 写明卡在哪条前置上；delegated 指向在盘的记录",
        f"越界判定 {bad_verdict or '无'} / 空前置 {blocked_empty or '无'} / 失效委派 {delegated_broken or '无'}",
    )

    # ⑤ executed 必须有带数字的观测值。
    empty_observed = [
        str(record.get("name"))
        for record in executed
        if not re.search(r"\d", str(record.get("observed", "")))
    ]
    check(
        not empty_observed,
        "每条 executed 能力都记了带数字的观测值（跑出 0 笔成交的通过是空跑）",
        f"无数字观测 {empty_observed or '无'}",
    )

    # ⑥ 能力名唯一 + 每条 evidence 在盘。
    names = [str(record.get("name")) for record in records]
    duplicates = sorted({name for name in names if names.count(name) > 1})
    missing_evidence = sorted(
        {
            f"{record.get('name')}:{item}"
            for record in records
            for item in (record.get("evidence") or [])
            if not (ROOT / str(item)).exists()
        }
    )
    check(
        not duplicates and not missing_evidence,
        "能力名唯一，且每条 evidence 路径都在盘",
        f"重名 {duplicates or '无'} / 证据缺失 {missing_evidence or '无'}",
    )


# —— 量化常见场景登记面：把「使用者嘴里的场景」逐条对上真命令（V13 R28）——

QUANT_SCENARIOS_FILE = "maturity/quant_scenarios.yaml"
QUANT_SCENARIOS_PROBE = "tools/quant_scenario_probe.py"
QUANT_SCENARIO_STATUSES = ("executed", "declared_not_executed", "missing", "blocked")
# 非 executed 的三档**必须**给出下一步闸门：缺口被藏起来，下一次读的人就会把它当"已支持"。
QUANT_SCENARIO_GATED = ("declared_not_executed", "missing", "blocked")
QUANT_SCENARIO_BUILTIN_SOURCE = "crates/qx-strategy/src/builtin/config.rs"
# The product's ten classic single-leg strategies must all have a real, non-zero
# fill in the generated scenario evidence. These are user-facing selections,
# not merely enum variants or unit-level signal assertions.
QUANT_SCENARIO_CLASSIC_BUILTINS = {
    "trend_following": "sma_cross",
    "momentum": "momentum",
    "mean_reversion": "mean_reversion",
    "breakout": "donchian_breakout",
    "grid_trading": "grid",
    "oscillator_reversion": "rsi",
    "ema_trend": "ema_cross",
    "macd_trend": "macd",
    "bollinger_reversion": "bollinger",
    "atr_trend": "atr_trend",
}
def _builtin_kind_names() -> set[str]:
    """`BuiltinStrategyKind::name()` 返回的那一串 snake_case 策略名（构造性取法）。

    场景记录里写一个不存在的策略名（改名 / 手写 / 笔误）当场红——`name()` 是 CLI 与配置共用的
    唯一词表，它没有的名字就是不存在。
    """
    body = _fn_body(_text_or_empty(ROOT / QUANT_SCENARIO_BUILTIN_SOURCE), "pub fn name(self)")
    return set(re.findall(r'=>\s*"([a-z_]+)"', body))


def quant_scenarios_check() -> None:
    """量化常见场景逐条对上真命令、跑出真数字、缺口写明下一步（V13 R28）。

    用户问的是「量化常见场景都落地了吗」。四份既有登记面都不回答**场景**这一轴：能力矩阵回答
    "每个领域走到哪一档"、能力阶梯回答"子系统在四档上的位置"、主链路调用图回答"每一段锚在哪个
    符号上"、能力执行记录回答"这些**能力**能不能执行"。场景与能力不是一回事——"目录里有 17 个
    内置策略"不告诉你"趋势跟踪 / 均值回归 / 配对套利 / 网格 / 多参数对比 …… 分别对应哪条命令、
    跑出来什么数、还有哪几个根本没落地"。

    六颗：① 记录在盘、自述齐全、四档 status 名册齐、场景非空；② 每条**声明了**内置策略名的
    `executed` 场景，其 `builtin_kind` 既在 `BuiltinStrategyKind::name()` 的词表里、也真出现在
    生成器脚本里；十类经典策略还必须分别有非零成交记录；
    ③ 每条 `anchor` 在盘；④ status 落在闭集里，且 `declared_not_executed` / `missing` /
    `blocked` 三档**必须**写 `next_gate`——缺口不许被藏起来；⑤ 每条 `executed` 记了**带数字**的
    观测值（跑出 0 笔成交的"通过"是空跑）；⑥ 场景名唯一，且每条 evidence 在盘。
    **恒发六颗、不早退。**

    刻意不在这里重跑探针（要编译产物、要几分钟），与 `capability_execution_check` 同一口径：
    门禁核"记录与生成器自洽且证据在盘"，真跑由 `tools/quant_scenario_probe.py` 负责。
    """
    path = ROOT / QUANT_SCENARIOS_FILE
    text = _text_or_empty(path)
    probe_src = _text_or_empty(ROOT / QUANT_SCENARIOS_PROBE)
    records = _parse_named_records(path, ("scenarios",)).get("scenarios", [])
    executed = [record for record in records if record.get("status") == "executed"]
    declared_statuses = set(re.findall(r"^  - (\w+)\s*$", text.split("scenarios:")[0], re.MULTILINE))

    # ① 记录在盘、自述齐全、四档名册齐、场景非空。
    check(
        bool(text)
        and bool(probe_src)
        and re.search(r"^kind:\s*quant-scenarios\s*$", text, re.MULTILINE) is not None
        and re.search(r"^schema_version:\s*1\s*$", text, re.MULTILINE) is not None
        and "generated_by:" in text
        and declared_statuses == set(QUANT_SCENARIO_STATUSES)
        and bool(records),
        "量化场景记录在盘、生成器在盘、自述 kind/schema_version/generated_by 齐全、四档 status 名册齐、场景非空",
        f"记录 {'有' if text else '缺'} / 生成器 {'有' if probe_src else '缺'} / "
        f"名册 {sorted(declared_statuses)} / 场景 {len(records)} 条",
    )

    # ② 声明了内置策略名的 executed 场景：名字既要在 `name()` 词表里，也要真出现在生成器里。
    #
    # 这一格只约束**声明了** `builtin_kind` 的记录——盘口撮合 / 跨语言多策略 / 多参数网格 /
    # 多数据源批量 / 事件控制面这五条本来就不由单个内置策略驱动，硬要它们写一个 `builtin_kind`
    # 只会逼出假值。第一版把「没声明」与「声明了假名」当成同一件事，于是基线自红五条——
    # 判据把**合法的缺省**读成了违规，与它要防的「凭空写一个不存在的策略名」不是一回事。
    #
    # 生成器联动——记录是探针跑出来的，声明的策略名必须能在 `tools/quant_scenario_probe.py`
    #     里找到（与 `capability_execution_check` ② 同一把尺：记录不许脱离生成器手写）。
    known_kinds = _builtin_kind_names()
    bound = [record for record in executed if str(record.get("builtin_kind", "")).strip()]
    unknown_kind = [
        f"{record.get('name')}:{record.get('builtin_kind')}"
        for record in bound
        if str(record.get("builtin_kind", "")) not in known_kinds
    ]
    not_in_generator = [
        f"{record.get('name')}:{record.get('builtin_kind')}"
        for record in bound
        if str(record.get("builtin_kind", "")) not in probe_src
    ]
    by_name = {str(record.get("name")): record for record in records}
    classic_not_executed = []
    for scenario_name, builtin_kind in QUANT_SCENARIO_CLASSIC_BUILTINS.items():
        record = by_name.get(scenario_name, {})
        fill_match = re.search(r"\bfills=(\d+)", str(record.get("observed", "")))
        if (
            record.get("status") != "executed"
            or record.get("builtin_kind") != builtin_kind
            or fill_match is None
            or int(fill_match.group(1)) <= 0
        ):
            classic_not_executed.append(scenario_name)
    check(
        bool(known_kinds)
        and not unknown_kind
        and not not_in_generator
        and not classic_not_executed,
        "每条声明了内置策略名的 executed 场景，其策略名既在 BuiltinStrategyKind::name() 的词表里、"
        "也真出现在生成器脚本里，且十类经典策略均有非零成交记录",
        f"词表 {len(known_kinds)} 个 / 绑定 {len(bound)} 条 / "
        f"未认 {unknown_kind or '无'} / 生成器缺 {not_in_generator or '无'} / "
        f"经典场景未闭环 {classic_not_executed or '无'}",
    )

    # ③ 每条 anchor 在盘。
    missing_anchor = [
        str(record.get("name"))
        for record in records
        if not (ROOT / str(record.get("anchor", ""))).exists()
    ]
    check(
        not missing_anchor,
        "每条场景的 anchor 路径都在盘（场景不许锚在不存在的落点上）",
        f"锚点缺失 {missing_anchor or '无'}",
    )

    # ④ status 闭集 + 非 executed 三档必须写明下一步闸门。
    bad_status = [
        str(record.get("name"))
        for record in records
        if record.get("status") not in QUANT_SCENARIO_STATUSES
    ]
    missing_gate = [
        str(record.get("name"))
        for record in records
        if record.get("status") in QUANT_SCENARIO_GATED
        and not str(record.get("next_gate", "")).strip()
    ]
    check(
        not bad_status and not missing_gate,
        "status 落在闭集里，且未落地的三档都写明了下一步闸门（缺口不许被藏起来）",
        f"越界 {bad_status or '无'} / 缺下一步 {missing_gate or '无'}",
    )

    # ⑤ executed 必须有带数字的观测值。
    empty_observed = [
        str(record.get("name"))
        for record in executed
        if not re.search(r"\d", str(record.get("observed", "")))
    ]
    check(
        not empty_observed,
        "每条 executed 场景都记了带数字的观测值（跑出 0 笔成交的通过是空跑）",
        f"无数字观测 {empty_observed or '无'}",
    )

    # ⑥ 场景名唯一 + 每条 evidence 在盘。
    names = [str(record.get("name")) for record in records]
    duplicates = sorted({name for name in names if names.count(name) > 1})
    missing_evidence = sorted(
        {
            f"{record.get('name')}:{item}"
            for record in records
            for item in (record.get("evidence") or [])
            if not (ROOT / str(item)).exists()
        }
    )
    check(
        not duplicates and not missing_evidence,
        "场景名唯一，且每条 evidence 路径都在盘",
        f"重名 {duplicates or '无'} / 证据缺失 {missing_evidence or '无'}",
    )


# —— 实验切分与基准：把方案 §8 点名的 OOS/走查与基准列从纸面声明变成真算出来的数（V13 R28）——

EXPERIMENT_SPLIT_FILE = "crates/qx-app/src/cases/experiment_split.rs"
EXPERIMENT_RUN_FILE = "crates/qx-app/src/cases/run_experiment.rs"
EXPERIMENT_TESTS_FILE = "crates/qx-app/tests/experiment_split.rs"
EXPERIMENT_SPEC_SOURCE = "crates/qx-spec/src/experiment.rs"
EXPERIMENT_SPLIT_TESTS = (
    "a_split_plan_yields_a_reproducible_out_of_sample_score",
    "walk_forward_rolls_by_step_bars",
    "baselines_use_the_close_series_and_zero_signal_is_flat",
    "an_unknown_baseline_name_is_rejected",
    "a_split_plan_that_does_not_fit_the_sample_is_a_fidelity_gap",
    "omitting_the_new_knobs_keeps_the_spec_and_report_byte_identical",
)


def _split_rule_conditions(text: str, receiver: str) -> list[str]:
    """取 `if <receiver>.xxx ... {` 形式的条件表达式，剥掉接收者前缀并归一化空白。

    用来把两份**同形但分处两个 crate** 的切分校验逐条对上：`qx-spec` 的规则写在
    `ExperimentSpec::validate` 里（接收者是 `split`），`qx-app` 的写在
    `ExperimentSplitPlan::validate` 里（接收者是 `self`）。剥掉接收者之后两者应当**逐字相同**。
    """
    found: list[str] = []
    for line in text.splitlines():
        matched = re.match(rf"\s*if\s+(!?{re.escape(receiver)}\.[^;]*?)\s*\{{\s*$", line)
        if matched:
            condition = matched.group(1).replace(f"{receiver}.", "")
            found.append(re.sub(r"\s+", " ", condition))
    return found


def experiment_split_plan_check() -> None:
    """`qx_spec::SplitPlan` 与 `EXPERIMENT_BASELINES` 从**纸面声明**变成**真被执行的数**（V13 R28）。

    立案：`SplitPlan` 有完整的字段与内部一致性校验、`EXPERIMENT_BASELINES` 被
    `ExperimentSpec::validate` 逐值校验——但三个实验执行者**一次都没有引用** split / walk /
    train / test，也没有任何地方算出 buy-and-hold 或 zero-signal 的收益。于是「这轮回测赚了
    113 bps」既没有样本外对照、也没有参照物。方案 §8「参数实验」点名的 OOS/WFA 因此是一条
    纸面承诺——`quant_scenarios_check` 把这一格判成 `declared_not_executed`，本族负责让它
    变成 `executed` 之后**不许悄悄退回去**。

    六颗：① 切分模块在盘且被 `mod` 挂载，`RunExperimentSpec` 真的长出两个旋钮、且两处都带
    `skip_serializing_if`（**纯加法**保证：不写这两格的旧 spec 必须序列化回原样，否则规格指纹
    一变，任何旧 `.experiment.json` 都会报 Conflict）；② `ExperimentSplitPlan::validate` 的三条
    规则与 `qx-spec` 那份**逐条相同**（同一份语义两处各写一半就会让"读得进来"与"跑得起来"分裂）；
    ③ `EXPERIMENT_BASELINE_NAMES` 与 `qx_spec::EXPERIMENT_BASELINES` 逐值相等；④ **选参只读训练窗、
    报分只读测试窗**（这是走查与"整段跑一遍再切片"的分界，反了就是把测试窗信息泄漏进选参）；
    ⑤ `buy-and-hold` 用的是**收盘价序列**而不是策略权益曲线；⑥ 六条行为用例在盘。
    **恒发六颗、不早退。**
    """
    split_src = _text_or_empty(ROOT / EXPERIMENT_SPLIT_FILE)
    run_src = _text_or_empty(ROOT / EXPERIMENT_RUN_FILE)
    spec_src = _text_or_empty(ROOT / EXPERIMENT_SPEC_SOURCE)
    tests_src = _text_or_empty(ROOT / EXPERIMENT_TESTS_FILE)
    cases_mod = _text_or_empty(ROOT / "crates/qx-app/src/cases/mod.rs")

    # ① 模块在盘、被挂载，两个旋钮都在且都带 skip_serializing_if。
    mounted = "mod experiment_split;" in cases_mod
    knobs = (
        "pub split_plan: Option<ExperimentSplitPlan>," in run_src
        and "pub baselines: Vec<String>," in run_src
        and run_src.count('skip_serializing_if = "Option::is_none"') >= 2
        and run_src.count('skip_serializing_if = "Vec::is_empty"') >= 2
    )
    check(
        bool(split_src) and mounted and knobs,
        "切分模块在盘且被挂载；`RunExperimentSpec` 的两个旋钮都在，且 spec 与报告两处都带 "
        "`skip_serializing_if`（不写这两格的旧 spec 序列化回原样，是纯加法）",
        f"模块 {'有' if split_src else '缺'} / 挂载 {'有' if mounted else '缺'} / 旋钮 {'齐' if knobs else '缺'}",
    )

    python_app = _text_or_empty(ROOT / "python/qianxing/app.py")
    experiment_grid_src = _text_or_empty(ROOT / "crates/qx-app/src/cases/experiment_grid.rs")
    experiment_search_src = _text_or_empty(ROOT / "crates/qx-app/src/cases/experiment_search.rs")
    multi_market_experiment_src = _text_or_empty(
        ROOT / "crates/qx-app/src/cases/run_multi_market_experiment.rs"
    )
    python_parameter_start = python_app.find("class ExperimentParameterSpace:")
    python_parameter_end = python_app.find("\n\n@dataclass", python_parameter_start)
    python_parameter_source = (
        python_app[python_parameter_start:python_parameter_end]
        if python_parameter_start >= 0 and python_parameter_end > python_parameter_start
        else ""
    )
    python_parameter_vocab_match = re.search(
        r"name:\s*Literal\[(.*?)\]\s*values:\s*tuple\[int,\s*\.\.\.\]",
        python_parameter_source,
        re.S,
    )
    python_parameter_vocab = (
        re.findall(r'"([^\"]+)"', python_parameter_vocab_match.group(1))
        if python_parameter_vocab_match
        else []
    )
    app_parameter_struct = re.search(
        r"pub struct ExperimentParameterSpace\s*\{([^}]*)\}", run_src, re.S
    )
    app_parameter_fields = (
        re.findall(r"pub (name|values): ([^,\n]+),", app_parameter_struct.group(1))
        if app_parameter_struct
        else []
    )
    spec_parameter_struct = re.search(
        r"pub struct ParameterSpace\s*\{([^}]*)\}", spec_src, re.S
    )
    spec_parameter_fields = (
        re.findall(r"pub (name|values): ([^,\n]+),", spec_parameter_struct.group(1))
        if spec_parameter_struct
        else []
    )
    bar_grid = _fn_body(experiment_grid_src, "pub(super) fn validate_grid(")
    depth_grid = _fn_body(experiment_grid_src, "pub(super) fn validate_depth_grid(")
    bar_vocab_match = re.search(r"let supported = \[(.*?)\];", bar_grid, re.S)
    depth_vocab_match = re.search(
        r"const MAKER_PARAMETERS: &\[&str\] = &\[(.*?)\];", depth_grid, re.S
    )
    rust_parameter_vocab = (
        re.findall(r'"([^\"]+)"', bar_vocab_match.group(1))
        + re.findall(r'"([^\"]+)"', depth_vocab_match.group(1))
        if bar_vocab_match and depth_vocab_match
        else []
    )

    def schema_parameter_vocab(schema_name: str, definition_name: str) -> set[str]:
        try:
            schema = json.loads(
                _text_or_empty(ROOT / "schemas" / schema_name)
            )
            return set(
                schema["$defs"][definition_name]["properties"]["name"]["enum"]
            )
        except (KeyError, TypeError, json.JSONDecodeError):
            return set()

    bar_parameter_vocab = set(
        re.findall(r'"([^\"]+)"', bar_vocab_match.group(1))
    ) if bar_vocab_match else set()
    depth_parameter_vocab = bar_parameter_vocab | (
        set(re.findall(r'"([^\"]+)"', depth_vocab_match.group(1)))
        if depth_vocab_match
        else set()
    )
    bar_parameter_schemas = (
        "run-experiment-spec-v1.json",
        "run-multi-leg-experiment-spec-v1.json",
        "run-multi-market-experiment-spec-v1.json",
    )
    depth_parameter_schemas = (
        "run-depth-experiment-spec-v1.json",
        "run-multi-market-depth-experiment-spec-v1.json",
    )
    try:
        experiment_range_name_schema = json.loads(
            _text_or_empty(ROOT / "schemas/run-experiment-spec-v1.json")
        )["$defs"]["ExperimentParameterRange"]["properties"]["name"]
    except (KeyError, TypeError, json.JSONDecodeError):
        experiment_range_name_schema = {}
    experiment_range_struct = re.search(
        r"pub struct ExperimentParameterRange\s*\{([^}]*)\}",
        experiment_search_src,
        re.S,
    )
    experiment_range_fields = (
        re.findall(r"pub (name|min|max|step): ([^,\n]+),", experiment_range_struct.group(1))
        if experiment_range_struct
        else []
    )
    python_range_start = python_app.find("class ExperimentParameterRange:")
    python_range_end = python_app.find("\n\n@dataclass", python_range_start)
    python_range_source = (
        python_app[python_range_start:python_range_end]
        if python_range_start >= 0 and python_range_end > python_range_start
        else ""
    )
    callback_range_validation = _fn_body(
        multi_market_experiment_src, "fn validate_callback_parameter_ranges("
    )
    range_names_are_contextually_validated = (
        experiment_range_fields
        == [("name", "String"), ("min", "i128"), ("max", "i128"), ("step", "i128")]
        and re.search(r"^\s*name: str\s*$", python_range_source, re.M)
        and experiment_range_name_schema
        == {
            "type": "string",
            "minLength": 1,
            "maxLength": 64,
            "pattern": "^[A-Za-z_][A-Za-z0-9_]*$",
        }
        and "validate_grid(strategy, std::slice::from_ref(&dimension))?" in _fn_body(
            experiment_grid_src, "pub(super) fn validate_continuous_grid("
        )
        and "apply_parameters(" in _fn_body(
            experiment_grid_src, "pub(super) fn validate_continuous_grid("
        )
        and "range.name.len() <= 64" in callback_range_validation
        and "range.point_count().is_none()" in callback_range_validation
        and "continuous_domain_cardinality(ranges)" in callback_range_validation
    )
    parameter_schema_shapes_match = (
        all(
            schema_parameter_vocab(name, "ExperimentParameterSpace")
            == bar_parameter_vocab
            for name in bar_parameter_schemas
        )
        and all(
            schema_parameter_vocab(name, "ExperimentParameterSpace")
            == depth_parameter_vocab
            for name in depth_parameter_schemas
        )
        and schema_parameter_vocab(
            "run-experiment-spec-v1.json", "ExperimentParameterRange"
        )
        == set()
        and range_names_are_contextually_validated
    )
    parameter_shape_mirror = (
        app_parameter_fields == [("name", "String"), ("values", "Vec<i128>")]
        and bool(python_parameter_vocab_match)
        and "def validate(" not in python_parameter_source
        and 'return {"name": self.name, "values": list(self.values)}' in python_parameter_source
        and set(python_parameter_vocab) == set(rust_parameter_vocab)
        and spec_parameter_fields == [("name", "String"), ("values", "Vec<String>")]
        and parameter_schema_shapes_match
    )
    python_split_start = python_app.find("class ExperimentSplitPlan:")
    python_split_end = python_app.find("\n\n@dataclass", python_split_start)
    python_split_source = (
        python_app[python_split_start:python_split_end]
        if python_split_start >= 0 and python_split_end > python_split_start
        else ""
    )
    python_split_fields = re.findall(
        r"^    (train_bars|test_bars|walk_forward|step_bars|purge_bars|embargo_bars): (int|bool)(?: = [^\n]+)?$",
        python_split_source,
        re.M,
    )
    python_split_shape = (
        python_split_fields
        == [
            ("train_bars", "int"),
            ("test_bars", "int"),
            ("walk_forward", "bool"),
            ("step_bars", "int"),
            ("purge_bars", "int"),
            ("embargo_bars", "int"),
        ]
        and "def validate(" not in python_split_source
        and all(f'"{field}"' in python_split_source for field, _ in python_split_fields)
    )

    split_plan_is_single_source = (
        "pub use qx_spec::{" in split_src
        and "SplitPlan as ExperimentSplitPlan" in split_src
        and "pub struct ExperimentSplitPlan" not in split_src
        and 'pub struct SplitPlan {' in spec_src
        and python_split_shape
        and parameter_shape_mirror
    )
    check(
        split_plan_is_single_source,
        "qx-app 直接复用 qx-spec::SplitPlan；实验参数 Python 镜像与 qx-app 字段/词表对齐；连续参数名由 schema 约束标识符并按使用场景在 Rust 校验",
        f"SplitPlan 单源别名 {'有' if 'pub use qx_spec::{SplitPlan as ExperimentSplitPlan' in split_src else '缺'} / Python 镜像 {'相符' if python_split_shape else '不符'} / 参数空间形状与上下文校验 {'相符' if parameter_shape_mirror else '不符'}",
    )

    # ② qx-spec owns validation and both spec loading and execution call it.
    spec_rules = _split_rule_conditions(
        _fn_body(spec_src, "pub fn validate(&self) -> Result<(), String>"), "self"
    )
    app_has_no_duplicate_validator = "pub fn validate(&self)" not in split_src
    app_calls_shared_validator = (
        "plan.validate()" in run_src
        and ".map_err(" in run_src[run_src.find("plan.validate()") :]
        and "self.split_plan.validate()?;" in spec_src
    )
    check(
        len(spec_rules) == 6 and app_has_no_duplicate_validator and app_calls_shared_validator,
        "切分形状只由 qx-spec::SplitPlan 校验，序列化规格与 qx-app 执行入口调用同一实现",
        f"qx-spec {len(spec_rules)} 条 / qx-app 无重复校验 {app_has_no_duplicate_validator} / 两入口共用 {app_calls_shared_validator}",
    )

    # ③ qx-spec owns the vocabulary. qx-app re-exports its public constant;
    # Python remains a shape mirror whose Literal domain must stay aligned without validation.
    def _baseline_vocab(text: str, name: str) -> list[str]:
        matched = re.search(rf"{name}: \[&str; \d+\] = \[([^\]]*)\]", text)
        if not matched:
            return []
        return re.findall(r'"([^"]+)"', matched.group(1))

    spec_vocab = _baseline_vocab(spec_src, "EXPERIMENT_BASELINES")
    python_baselines = re.search(
        r"baselines:\s*tuple\[Literal\[([^\]]+)\],\s*\.\.\.\]\s*=",
        python_app,
    )
    python_vocab = (
        re.findall(r'"([^"]+)"', python_baselines.group(1)) if python_baselines else []
    )
    baseline_generated = (
        "EXPERIMENT_BASELINES as EXPERIMENT_BASELINE_NAMES" in split_src
        and "pub const EXPERIMENT_BASELINE_NAMES" not in run_src
        and "pub use super::experiment_split::EXPERIMENT_BASELINE_NAMES;" in run_src
    )
    check(
        bool(spec_vocab) and spec_vocab == python_vocab and baseline_generated,
        "`EXPERIMENT_BASELINE_NAMES`（qx-app）与 `qx_spec::EXPERIMENT_BASELINES` 逐值相等",
        f"qx-spec {spec_vocab} / Python {python_vocab} / qx-app 重导出={'是' if baseline_generated else '否'}",
    )

    # ④ 选参读训练窗、报分读测试窗——反了就是把测试窗信息泄漏进选参。
    selects_on_train = "window_return_bps(values, ranges.train[0], ranges.train[1])" in split_src
    reports_on_test = (
        "out_of_sample_return_bps: window_return_bps(values, ranges.test[0], ranges.test[1])," in split_src
    )
    check(
        selects_on_train and reports_on_test,
        "选参只读训练窗、样本外分数只读测试窗（走查与『整段跑一遍再切片』的分界）",
        f"选参读训练窗 {'是' if selects_on_train else '否'} / 报分读测试窗 {'是' if reports_on_test else '否'}",
    )

    # ⑤ buy-and-hold 用收盘价序列，不是策略权益曲线。
    baseline_body = _fn_body(split_src, "pub(super) fn evaluate_baselines(")
    uses_closes = "bars.iter().map(|bar| bar.close)" in baseline_body
    check(
        uses_closes and '"zero-signal" =>' in baseline_body,
        "`buy-and-hold` 用收盘价序列算（策略权益曲线不是买入持有），`zero-signal` 是恒等式",
        f"收盘价序列 {'在' if uses_closes else '缺'}",
    )

    # ⑥ 六条行为用例在盘。
    missing_tests = [name for name in EXPERIMENT_SPLIT_TESTS if f"fn {name}(" not in tests_src]
    check(
        bool(tests_src) and not missing_tests,
        "切分与基准的六条行为用例都在盘（静态判据只是快闸，真牙齿是那六条）",
        f"缺 {missing_tests or '无'}",
    )


def capability_matrix_check() -> None:
    """方案 §2 的「基线复核产物」：能力矩阵逐格与真实代码对账。

    十二颗：① 矩阵在盘、自述 kind 与 schema_version 正确、三段（domains/venues/providers）非空；
    ② `levels` 恰是方案 §2 点名的五态且顺序一致（档位是闭集，不许就地长出新档）；③ 全表没有把
    能力写成布尔值的地方——判据自带反例自证；④ `domains` 名册 == 方案 §2 基线表的八个领域；
    ⑤ 每个领域的档位落在闭集里；⑥ 每个领域都写了至少一条限制（「不得掩盖限制」的可核验形态）；
    ⑦ 每个领域的证据里至少有一条仓库路径且每条都在盘；⑧ 每个领域都写了下一个闸门；
    ⑨ venue 名册 == 生产代码里真实的 `impl Venue for X`，且每条记录的 `impl` 就是含该实现的文件
    （多一个 = 凭空声明一个不存在的 venue；少一个 = 有 venue 活着却没人给它评档）；
    ⑩ 每个 venue 逐格给齐 §4.2 的字段名册且档位合法、`verified_version` 非空；⑪ provider 名册 ==
    生产代码里真实的 `impl DataProvider for X`，且逐格给齐数据面字段名册；⑫ 外部 venue 声称
    `sandbox`/`order_type` 已验时，必须真有 outcome=pass 的 testnet 记录（没有证据不得翻真，
    与 `capabilities_check` 同一把尺）。刻意不早退：这一族恒发十二条。
    """
    text = _text_or_empty(ROOT / CAPABILITY_MATRIX_FILE)
    sections = _parse_named_records(
        ROOT / CAPABILITY_MATRIX_FILE, ("domains", "venues", "providers")
    )
    domains, venues, providers = sections["domains"], sections["venues"], sections["providers"]
    declared_kind = re.search(r"^kind:\s*(\S+)\s*$", text, re.MULTILINE)
    declared_schema = re.search(r"^schema_version:\s*(\d+)\s*$", text, re.MULTILINE)
    check(
        declared_kind is not None
        and declared_kind.group(1) == CAPABILITY_MATRIX_KIND
        and declared_schema is not None
        and declared_schema.group(1) == "1"
        and bool(domains)
        and bool(venues)
        and bool(providers),
        "能力矩阵在盘、自述 kind 与 schema_version 正确、三段（domains/venues/providers）非空",
        f"kind {declared_kind and declared_kind.group(1)}；"
        f"schema {declared_schema and declared_schema.group(1)}；"
        f"domains {len(domains)} / venues {len(venues)} / providers {len(providers)}",
    )

    levels = _matrix_roster("levels")
    check(
        levels == list(CAPABILITY_MATRIX_LEVELS),
        "`levels` 恰是方案 §2 点名的五态且顺序一致（档位词表是闭集，不许就地长出新档）",
        f"实测 {levels}",
    )

    offenders = _boolean_capability_flags(text)
    check(
        not offenders
        and _boolean_capability_flags("    supported: true\n") == ["supported=true"]
        and _boolean_capability_flags("    market: partial\n") == [],
        "全表没有把能力写成布尔值的地方（方案 §2：不得用 `supported=true` 掩盖限制）",
        f"越界 {offenders}",
    )

    domain_names = [str(record.get("name", "")) for record in domains]
    check(
        len(domain_names) == len(set(domain_names))
        and set(domain_names) == set(CAPABILITY_MATRIX_DOMAINS),
        "`domains` 名册 == 方案 §2 基线表的八个领域（少一个就是有缺口被藏起来了）",
        f"缺 {sorted(set(CAPABILITY_MATRIX_DOMAINS) - set(domain_names))}；"
        f"多 {sorted(set(domain_names) - set(CAPABILITY_MATRIX_DOMAINS))}",
    )

    bad_levels = [
        f"{record.get('name')}:{record.get('level')}"
        for record in domains
        if str(record.get("level", "")) not in CAPABILITY_MATRIX_LEVELS
    ]
    check(not bad_levels, "每个领域的档位都落在五态闭集里", f"越界 {bad_levels}")

    no_limits = [
        str(record.get("name"))
        for record in domains
        if not [item for item in record.get("limitations", []) if str(item).strip()]
    ]
    check(
        not no_limits,
        "每个领域都写了至少一条限制（「不得掩盖限制」的可核验形态）",
        f"缺限制 {no_limits}",
    )

    path_token = re.compile(
        r"(?:crates|tools|deploy|maturity|docs|schemas|python|cpp|web|\.github)"
        r"/[^\s，。；、）()「」\"`]+"
    )
    missing_evidence: list[str] = []
    thin_evidence: list[str] = []
    for record in domains:
        tokens = [
            token.rstrip(".,:;")
            for entry in record.get("evidence", [])
            for token in path_token.findall(str(entry))
        ]
        if not tokens:
            thin_evidence.append(str(record.get("name")))
            continue
        missing_evidence.extend(
            f"{record.get('name')}:{token}" for token in tokens if not (ROOT / token).exists()
        )
    check(
        not missing_evidence and not thin_evidence,
        "每个领域的证据里至少有一条仓库路径，且每条都在盘（证据不是形容词）",
        f"失效 {sorted(set(missing_evidence))}；无路径 {thin_evidence}",
    )

    no_gate = [
        str(record.get("name"))
        for record in domains
        if not str(record.get("next_gate", "")).strip()
    ]
    check(not no_gate, "每个领域都写了下一个闸门（缺口要有人接着）", f"缺闸门 {no_gate}")

    impls = _production_trait_impls()
    venue_names = [str(record.get("name", "")) for record in venues]
    venue_mismatch = [
        f"{record.get('name')}:impl={record.get('impl')} "
        f"实为 {impls['Venue'].get(str(record.get('name')), '无实现')}"
        for record in venues
        if impls["Venue"].get(str(record.get("name"))) != str(record.get("impl", ""))
    ]
    check(
        len(venue_names) == len(set(venue_names))
        and set(venue_names) == set(impls["Venue"])
        and not venue_mismatch,
        "venue 名册 == 生产代码里真实的 `impl Venue for X`，且 `impl` 就是含该实现的文件",
        f"缺 {sorted(set(impls['Venue']) - set(venue_names))}；"
        f"多 {sorted(set(venue_names) - set(impls['Venue']))}；impl 不符 {venue_mismatch}",
    )

    capability_impl_gaps: list[str] = []
    for name, relative in impls["Venue"].items():
        source = _text_or_empty(ROOT / relative)
        start = source.find(f"impl Venue for {name}")
        next_impl = source.find("\nimpl ", start + 1) if start >= 0 else -1
        block = source[start : next_impl if next_impl >= 0 else len(source)]
        if start < 0 or "fn capabilities(" not in block:
            capability_impl_gaps.append(f"{name}:{relative}")
    zhenlu_source = _text_or_empty(ROOT / "crates/qx-zhenlu/src/lib.rs")
    execution_source = _text_or_empty(ROOT / "crates/qx-execution/src/lib.rs")
    capability_test_source = _text_or_empty(ROOT / "crates/qx-execution/src/tests/gateway_port.rs")
    binance_source = _text_or_empty(ROOT / "crates/qx-adapter/src/binance.rs")
    ccxt_source = _text_or_empty(ROOT / "crates/qx-adapter/src/ccxt.rs")
    capability_impl_source = _text_or_empty(ROOT / "crates/qx-zhenlu/src/venue_capabilities.rs")
    capability_boundary_ready = (
        re.search(r"pub trait Venue\s*\{[\s\S]*?fn capabilities\(", zhenlu_source)
        is not None
        and "self.venue.validate_submit_capabilities(&order)?" in execution_source
        and "self.venue.capabilities().validate_cancel()?" in execution_source
        and ".require_query()?" in function_body(binance_source, "fetch_remote_snapshot")
        and ".require_reconciliation()?" in function_body(binance_source, "reconcile_remote")
        and ".require_query()?" in function_body(ccxt_source, "sync_order")
        and "VenueMarketScope::BinanceSpot" in capability_impl_source
        and "VenueMarketScope::RuntimeConfigured" in capability_impl_source
        and "venue_market_query_and_reconciliation_capabilities_are_enforced" in capability_test_source
    )
    check(
        not capability_impl_gaps and capability_boundary_ready,
        "每个生产 Venue 都实现运行时能力声明；提交/撤单、Binance 查询/对账与 CCXT 查询入口执行对应能力校验",
        f"缺声明 {capability_impl_gaps}；统一边界 {'完整' if capability_boundary_ready else '缺失'}",
    )

    provider_capability_source = _text_or_empty(ROOT / "crates/qx-provider/src/lib.rs")
    provider_match_source = _text_or_empty(ROOT / "crates/qx-provider/src/result.rs")
    provider_registry_tests = _text_or_empty(ROOT / "crates/qx-provider/src/tests.rs")
    provider_depth_source = _text_or_empty(
        ROOT / "crates/qx-app/src/cases/run_provider_depth_backtest.rs"
    )
    provider_tier_contract_ready = (
        "pub enum MarketDataTier" in provider_capability_source
        and "pub required_data_tier: Option<MarketDataTier>" in provider_capability_source
        and "pub data_tiers: BTreeSet<MarketDataTier>" in provider_capability_source
        and "self.data_tiers.contains(&tier)" in provider_match_source
        and "self.data_tiers.iter().any(|tier| match tier" in provider_match_source
        and "self.data_kinds.contains(&DataKind::Bar)" in provider_match_source
        and "self.data_kinds.contains(&DataKind::Quote)" in provider_match_source
        and "Provider" in provider_depth_source
        and "self.data_request.requirements.required_data_tier != expected_tier"
        in provider_depth_source
        and "provider_registry_filters_by_declared_market_data_tier_before_io"
        in provider_registry_tests
        and "provider_cannot_declare_market_payloads_without_a_tier"
        in provider_registry_tests
    )
    check(
        provider_tier_contract_ready,
        "Provider 声明的数据档位参与请求预检，深度回测档位与请求/Provider 能力一致",
        "Provider tier request matching, pre-I/O rejection, or depth-run binding is missing",
    )

    venue_gaps = [
        f"{record.get('name')}:{field}"
        for record in venues
        for field in CAPABILITY_MATRIX_VENUE_FIELDS
        if str(record.get(field, "")) not in CAPABILITY_MATRIX_LEVELS
    ]
    version_gaps = [
        str(record.get("name"))
        for record in venues
        if not str(record.get("verified_version", "")).strip()
    ]
    check(
        not venue_gaps and not version_gaps,
        "每个 venue 逐格给齐 §4.2 的字段名册且档位合法、`verified_version` 非空",
        f"缺格或档位非法 {venue_gaps}；缺版本 {version_gaps}",
    )

    provider_names = [str(record.get("name", "")) for record in providers]
    provider_gaps = [
        f"{record.get('name')}:{field}"
        for record in providers
        for field in CAPABILITY_MATRIX_PROVIDER_FIELDS
        if str(record.get(field, "")) not in CAPABILITY_MATRIX_LEVELS
    ]
    check(
        len(provider_names) == len(set(provider_names))
        and set(provider_names) == set(impls["DataProvider"])
        and not provider_gaps,
        "provider 名册 == 生产代码里真实的 `impl DataProvider for X`，且逐格给齐数据面字段名册",
        f"缺 {sorted(set(impls['DataProvider']) - set(provider_names))}；"
        f"多 {sorted(set(provider_names) - set(impls['DataProvider']))}；缺格 {provider_gaps}",
    )

    tally = _evidence_outcome_tally(CAPABILITY_MATRIX_EVIDENCE_ROOT)
    passing = tally.get("pass", 0) + tally.get("passed", 0)
    overclaimed = [
        f"{record.get('name')}:{field}"
        for record in venues
        if str(record.get("kind", "")) == "external_venue"
        for field in CAPABILITY_MATRIX_EVIDENCE_BACKED_FIELDS
        if str(record.get(field, "")) == "implemented-and-verified"
    ]
    check(
        not overclaimed or passing > 0,
        "外部 venue 声称 `sandbox`/`order_type` 已验时必须有 outcome=pass 的 testnet 记录"
        "（没有证据不得翻真，与 `capabilities_check` 同一把尺）",
        f"越界 {overclaimed}；testnet 记录 {tally or '无'}（pass {passing}）",
    )


def capability_crosswalk_check() -> None:
    """Bind every product matrix row to stable IDs and internal evidence keys."""
    sections = ("domains", "venues", "providers")
    matrix = _parse_named_records(ROOT / CAPABILITY_MATRIX_FILE, sections)
    matrix_rows = [record for section in sections for record in matrix[section]]
    bindings = _parse_named_records(ROOT / CAPABILITY_CROSSWALK_FILE, ("bindings",))["bindings"]
    crosswalk_text = _text_or_empty(ROOT / CAPABILITY_CROSSWALK_FILE)
    declared_kind = re.search(r"^kind:\s*(\S+)\s*$", crosswalk_text, re.MULTILINE)
    declared_schema = re.search(r"^schema_version:\s*(\d+)\s*$", crosswalk_text, re.MULTILINE)
    check(
        declared_kind is not None
        and declared_kind.group(1) == CAPABILITY_CROSSWALK_KIND
        and declared_schema is not None
        and declared_schema.group(1) == "1"
        and bool(bindings),
        "能力 crosswalk 在盘、自述 kind/schema 正确且至少有一条绑定",
        f"kind {declared_kind and declared_kind.group(1)}；"
        f"schema {declared_schema and declared_schema.group(1)}；bindings {len(bindings)}",
    )

    id_pattern = re.compile(r"^qx\.(?:domain|venue|provider)\.[a-z][a-z0-9_]*$")
    matrix_ids = [str(record.get("capability_id", "")) for record in matrix_rows]
    missing_matrix_ids = [str(record.get("name")) for record in matrix_rows if not record.get("capability_id")]
    invalid_matrix_ids = [value for value in matrix_ids if not id_pattern.fullmatch(value)]
    binding_ids = [str(record.get("name", "")) for record in bindings]
    check(
        not missing_matrix_ids
        and not invalid_matrix_ids
        and len(matrix_ids) == len(set(matrix_ids))
        and len(binding_ids) == len(set(binding_ids))
        and set(binding_ids) == set(matrix_ids),
        "领域、Venue、Provider 均有唯一稳定 capability_id，crosswalk 与矩阵逐条双向对应",
        f"缺 ID {missing_matrix_ids}；非法 ID {invalid_matrix_ids}；"
        f"矩阵 ID 数 {len(matrix_ids)} / 绑定 ID 数 {len(binding_ids)}；"
        f"未绑定 {sorted(set(matrix_ids) - set(binding_ids))}；无矩阵项 {sorted(set(binding_ids) - set(matrix_ids))}",
    )

    matrix_by_id = {
        str(record.get("capability_id")): f"{section}/{record.get('name')}"
        for section in sections
        for record in matrix[section]
        if record.get("capability_id")
    }
    bad_matrix_refs = [
        f"{record.get('name')} -> {record.get('matrix_ref')} (expected {matrix_by_id.get(str(record.get('name')))})"
        for record in bindings
        if str(record.get("matrix_ref", "")) != matrix_by_id.get(str(record.get("name")))
    ]
    empty_evidence_refs = [
        str(record.get("name"))
        for record in bindings
        if not [item for item in record.get("maturity_refs", []) if str(item).strip()]
    ]
    check(
        not bad_matrix_refs and not empty_evidence_refs,
        "crosswalk 每条绑定都指向其唯一矩阵记录，并关联至少一条成熟度证据",
        f"矩阵引用错误 {bad_matrix_refs}；缺成熟度引用 {empty_evidence_refs}",
    )

    maturity_roster = _maturity_capability_roster()
    referenced_maturity = [
        str(item)
        for record in bindings
        for item in record.get("maturity_refs", [])
    ]
    unknown_maturity = sorted(set(referenced_maturity) - maturity_roster)
    unlinked_maturity = sorted(maturity_roster - set(referenced_maturity))
    duplicate_refs = [
        str(record.get("name"))
        for record in bindings
        if len(record.get("maturity_refs", [])) != len(set(record.get("maturity_refs", [])))
    ]
    check(
        bool(maturity_roster)
        and not unknown_maturity
        and not unlinked_maturity
        and not duplicate_refs,
        "每条成熟度登记都至少被一个产品 capability ID 引用，且不存在悬空或重复引用",
        f"未知证据键 {unknown_maturity}；未关联证据键 {unlinked_maturity}；重复引用 {duplicate_refs}",
    )

    catalog_path = ROOT / "crates/qx-api/src/capability_catalog.generated.json"
    try:
        catalog = json.loads(catalog_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
        catalog = {}
        catalog_error = str(error)
    else:
        catalog_error = ""
    python_catalog_path = ROOT / "crates/qx-python/src/capability_catalog.generated.json"
    try:
        python_catalog = json.loads(python_catalog_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
        python_catalog = {}
        python_catalog_error = str(error)
    else:
        python_catalog_error = ""
    check(
        not catalog_error
        and not python_catalog_error
        and python_catalog == catalog,
        "Python 原生账户读取预检使用与 API 同源的生成能力目录",
        f"API catalog error={catalog_error}; Python catalog error={python_catalog_error}; documents_equal={python_catalog == catalog}",
    )
    source_paths = (
        CAPABILITY_MATRIX_FILE,
        "maturity/capabilities.yaml",
        CAPABILITY_CROSSWALK_FILE,
    )
    expected_digests = {
        path: hashlib.sha256((ROOT / path).read_bytes()).hexdigest()
        for path in source_paths
        if (ROOT / path).is_file()
    }
    catalog_digests = catalog.get("source_sha256", {}) if isinstance(catalog, dict) else {}
    check(
        not catalog_error
        and catalog.get("kind") == "qianxing-capability-catalog"
        and catalog.get("schema_version") == 1
        and catalog_digests == expected_digests,
        "API 能力目录为有效生成物，且三份来源变更后必须重新生成",
        f"读取错误 {catalog_error or '无'}；kind/schema {catalog.get('kind')}/{catalog.get('schema_version')}；"
        f"摘要匹配 {catalog_digests == expected_digests}",
    )
    expected_ids = [str(record.get("capability_id", "")) for record in matrix_rows]
    details = catalog.get("capabilities", []) if isinstance(catalog, dict) else []
    index = catalog.get("index", []) if isinstance(catalog, dict) else []
    detail_ids = [entry.get("id") for entry in details if isinstance(entry, dict)] if isinstance(details, list) else []
    index_ids = [entry.get("id") for entry in index if isinstance(entry, dict)] if isinstance(index, list) else []
    bindings_by_id = {str(record.get("name")): record for record in bindings}
    catalog_errors: list[str] = []
    details_by_id = {entry.get("id"): entry for entry in details if isinstance(entry, dict)} if isinstance(details, list) else {}
    index_by_id = {entry.get("id"): entry for entry in index if isinstance(entry, dict)} if isinstance(index, list) else {}
    for capability_id in expected_ids:
        detail = details_by_id.get(capability_id)
        summary = index_by_id.get(capability_id)
        binding = bindings_by_id.get(capability_id)
        if not isinstance(detail, dict) or not isinstance(summary, dict) or binding is None:
            catalog_errors.append(f"{capability_id}: missing detail/index/binding")
            continue
        expected_refs = list(binding.get("maturity_refs", []))
        evidence = detail.get("maturity_evidence", [])
        evidence_ids = [item.get("id") for item in evidence if isinstance(item, dict)] if isinstance(evidence, list) else []
        if (
            detail.get("matrix_ref") != binding.get("matrix_ref")
            or summary.get("matrix_ref") != binding.get("matrix_ref")
            or summary.get("maturity_refs") != expected_refs
            or evidence_ids != expected_refs
        ):
            catalog_errors.append(f"{capability_id}: source projection differs from crosswalk")
    check(
        detail_ids == expected_ids and index_ids == expected_ids and not catalog_errors,
        "API 能力目录详情与轻索引逐条对应产品矩阵及成熟度 crosswalk",
        f"矩阵 {len(expected_ids)} 项 / 详情 {len(detail_ids)} 项 / 索引 {len(index_ids)} 项；错误 {catalog_errors}",
    )

    scope_errors: list[str] = []
    scope_facets: dict[str, set[str]] = {
        "venue": set(),
        "product": set(),
        "account_mode": set(),
        "account_models": set(),
        "margin_modes": set(),
        "position_modes": set(),
        "operations": set(),
        "order_types": set(),
        "quantity_units": set(),
    }
    scope_count = 0
    scope_fields = {
        "venue",
        "product",
        "account_mode",
        "account_models",
        "margin_modes",
        "position_modes",
        "operations",
        "order_shapes",
        "maturity_refs",
        "status",
        "evidence",
    }
    for detail in details if isinstance(details, list) else []:
        if not isinstance(detail, dict):
            continue
        capability_id = str(detail.get("id", "unknown"))
        scopes = detail.get("execution_scopes")
        if not isinstance(scopes, list):
            scope_errors.append(f"{capability_id}: execution_scopes is not an array")
            continue
        summary = index_by_id.get(capability_id, {})
        if summary.get("execution_scope_count") != len(scopes):
            scope_errors.append(f"{capability_id}: index execution_scope_count differs")
        if scopes and not capability_id.startswith("qx.venue."):
            scope_errors.append(f"{capability_id}: non-venue capability declares execution scopes")
        seen_scopes: set[tuple[object, ...]] = set()
        for scope in scopes:
            scope_count += 1
            if not isinstance(scope, dict) or set(scope) != scope_fields:
                scope_errors.append(f"{capability_id}: malformed execution scope fields")
                continue
            venue = scope.get("venue")
            product = scope.get("product")
            account_mode = scope.get("account_mode")
            account_models = scope.get("account_models")
            margin_modes = scope.get("margin_modes")
            position_modes = scope.get("position_modes")
            operations = scope.get("operations")
            order_shapes = scope.get("order_shapes")
            maturity_refs = scope.get("maturity_refs")
            evidence_paths = scope.get("evidence")
            if (
                not isinstance(venue, str)
                or venue != venue.strip().upper()
                or not isinstance(product, str)
                or product != product.strip().lower()
                or not isinstance(account_mode, str)
                or account_mode != account_mode.strip().lower()
                or scope.get("status") not in CAPABILITY_MATRIX_LEVELS
                or not isinstance(account_models, list)
                or not account_models
                or any(not isinstance(value, str) or value != value.strip().lower() for value in account_models)
                or len(account_models) != len(set(account_models))
                or not isinstance(margin_modes, list)
                or not margin_modes
                or any(not isinstance(value, str) or value != value.strip().lower() for value in margin_modes)
                or len(margin_modes) != len(set(margin_modes))
                or not isinstance(position_modes, list)
                or not position_modes
                or any(not isinstance(value, str) or value != value.strip().lower() for value in position_modes)
                or len(position_modes) != len(set(position_modes))
                or not isinstance(operations, list)
                or not operations
                or any(not isinstance(value, str) or value not in {"submit", "cancel"} for value in operations)
                or len(operations) != len(set(operations))
                or not isinstance(order_shapes, list)
                or not order_shapes
                or not isinstance(maturity_refs, list)
                or not maturity_refs
                or any(not isinstance(value, str) or not value.strip() for value in maturity_refs)
                or not isinstance(evidence_paths, list)
                or not evidence_paths
            ):
                scope_errors.append(f"{capability_id}: invalid execution scope vocabulary")
                continue
            missing_paths = [
                path for path in evidence_paths
                if not isinstance(path, str) or not (ROOT / path).is_file()
            ]
            if missing_paths:
                scope_errors.append(f"{capability_id}: missing scope evidence {missing_paths}")
            for shape in order_shapes:
                if (
                    not isinstance(shape, dict)
                    or set(shape) != {"order_type", "quantity_unit", "side"}
                    or shape.get("order_type") not in {"market", "limit"}
                    or shape.get("quantity_unit") not in {"base", "contracts", "quote"}
                    or shape.get("side") not in {"buy", "sell"}
                    or (
                        shape.get("quantity_unit") == "quote"
                        and (shape.get("order_type") != "market" or shape.get("side") != "buy")
                    )
                ):
                    scope_errors.append(f"{capability_id}: invalid order shape {shape}")
                elif isinstance(shape, dict):
                    scope_facets["order_types"].add(shape["order_type"])
                    scope_facets["quantity_units"].add(shape["quantity_unit"])
            expected_maturity_refs = set(summary.get("maturity_refs", []))
            if not set(maturity_refs).issubset(expected_maturity_refs):
                scope_errors.append(f"{capability_id}: scope maturity refs are not bound by crosswalk")
            identity = (venue, product, account_mode, tuple(sorted(account_models)))
            if identity in seen_scopes:
                scope_errors.append(f"{capability_id}: duplicate execution scope {identity}")
            seen_scopes.add(identity)
            scope_facets["venue"].add(venue)
            scope_facets["product"].add(product)
            scope_facets["account_mode"].add(account_mode)
            scope_facets["account_models"].update(account_models)
            scope_facets["margin_modes"].update(margin_modes)
            scope_facets["position_modes"].update(position_modes)
            scope_facets["operations"].update(operations)
    expected_scope_facets = {key: sorted(values) for key, values in scope_facets.items()}
    check(
        scope_count > 0
        and not scope_errors
        and catalog.get("execution_scope_facets") == expected_scope_facets,
        "交易范围目录字段、证据、索引计数及过滤提示一致",
        f"范围 {scope_count} 项；facets 一致 {catalog.get('execution_scope_facets') == expected_scope_facets}；错误 {scope_errors}",
    )

    account_scope_errors: list[str] = []
    account_scope_count = 0
    account_scope_fields = {
        "venue",
        "product",
        "account_models",
        "operations",
        "maturity_refs",
        "status",
        "evidence",
    }
    account_operations = {
        "balance.read",
        "orders.read",
        "positions.read",
        "cashflows.read",
        "funding.read",
        "account_settings.read",
    }
    for detail in details if isinstance(details, list) else []:
        if not isinstance(detail, dict):
            continue
        capability_id = str(detail.get("id", "unknown"))
        scopes = detail.get("account_query_scopes")
        if not isinstance(scopes, list):
            account_scope_errors.append(f"{capability_id}: account_query_scopes is not an array")
            continue
        summary = index_by_id.get(capability_id, {})
        if summary.get("account_query_scope_count") != len(scopes):
            account_scope_errors.append(f"{capability_id}: index account_query_scope_count differs")
        if scopes and not capability_id.startswith("qx.venue."):
            account_scope_errors.append(f"{capability_id}: non-venue capability declares account query scopes")
        seen_account_scopes: set[tuple[str, str, str]] = set()
        for scope in scopes:
            account_scope_count += 1
            if not isinstance(scope, dict) or set(scope) != account_scope_fields:
                account_scope_errors.append(f"{capability_id}: malformed account query scope fields")
                continue
            venue = scope.get("venue")
            product = scope.get("product")
            account_models = scope.get("account_models")
            operations = scope.get("operations")
            maturity_refs = scope.get("maturity_refs")
            evidence_paths = scope.get("evidence")
            if (
                not isinstance(venue, str)
                or venue != venue.strip().upper()
                or not isinstance(product, str)
                or product != product.strip().lower()
                or scope.get("status") not in CAPABILITY_MATRIX_LEVELS
                or not isinstance(account_models, list)
                or not account_models
                or any(not isinstance(value, str) or value != value.strip().lower() for value in account_models)
                or len(account_models) != len(set(account_models))
                or not isinstance(operations, list)
                or not operations
                or any(not isinstance(value, str) or value not in account_operations for value in operations)
                or len(operations) != len(set(operations))
                or not isinstance(maturity_refs, list)
                or not maturity_refs
                or any(not isinstance(value, str) or not value.strip() for value in maturity_refs)
                or not isinstance(evidence_paths, list)
                or not evidence_paths
            ):
                account_scope_errors.append(f"{capability_id}: invalid account query scope vocabulary")
                continue
            missing_paths = [
                path for path in evidence_paths
                if not isinstance(path, str) or not (ROOT / path).is_file()
            ]
            if missing_paths:
                account_scope_errors.append(f"{capability_id}: missing account query evidence {missing_paths}")
            expected_maturity_refs = set(summary.get("maturity_refs", []))
            if not set(maturity_refs).issubset(expected_maturity_refs):
                account_scope_errors.append(f"{capability_id}: account query maturity refs are not bound by crosswalk")
            for account_model in account_models:
                identity = (venue, product, account_model)
                if identity in seen_account_scopes:
                    account_scope_errors.append(f"{capability_id}: duplicate account query scope {identity}")
                seen_account_scopes.add(identity)
    check(
        account_scope_count > 0
        and not account_scope_errors,
        "账户私有查询范围逐项登记了字段、稳定操作名、成熟度引用、证据路径和索引计数",
        f"范围 {account_scope_count} 项；错误 {account_scope_errors}",
    )

    def ordered_source_markers(path: str, markers: list[str]) -> bool:
        source = _text_or_empty(ROOT / path)
        positions = [source.find(marker) for marker in markers]
        return all(position >= 0 for position in positions) and positions == sorted(positions)

    private_query_gate_order = (
        ordered_source_markers(
            "crates/qx-service/src/binance_reconcile_host.rs",
            [
                "require_account_query_execution_capability(",
                "let mut venue = create_venue(&worker)?;",
                ".fetch_and_reconcile()",
                ".fetch_account_balances(runtime_timestamp_ms())",
            ],
        )
        and ordered_source_markers(
            "crates/qx-service/src/ccxt_reconcile_host.rs",
            [
                "require_account_query_execution_capability(",
                "CcxtProcessClient::spawn(&python, &ccxt_config_path, None)",
                '"op": "fetch_balance"',
                'if query_allowed("cashflows.read")',
                '"op": "fetch_ledger"',
                '.filter(|_| query_allowed("funding.read"))',
                '"op": "fetch_funding_history"',
                'if query_allowed("positions.read")',
                '"op": "fetch_positions"',
            ],
        )
        and ordered_source_markers(
            "python/qianxing_ccxt/private_probe.py",
            [
                "app_account_query_capability_preflight_v1(json.dumps(spec))",
                "config = _config_from_file(args.config)",
                "client = CcxtExchangeClient(config)",
                "balance = client.fetch_balance()",
                "positions = client.fetch_positions(instruments)",
                "settings = client.fetch_contract_settings(str(instrument))",
            ],
        )
    )
    check(
        private_query_gate_order,
        "Binance/CCXT 对账与 Python sandbox 私有探针均先过账户查询能力门，CCXT 可选私有读取按声明执行",
        "账户私有查询可能在能力预检前创建连接器或调用未声明的私有接口",
    )

    markdown_path = ROOT / "docs/capability-catalog.md"
    markdown = _text_or_empty(markdown_path)
    expected_digest_marker = "<!-- Source SHA-256: " + "; ".join(
        f"{path}={digest}" for path, digest in expected_digests.items()
    ) + " -->"
    missing_markdown_ids = [
        capability_id
        for capability_id in expected_ids
        if f"| {capability_id} |" not in markdown
    ]
    missing_scope_rows = [
        f"{detail.get('id')}/{scope.get('venue')}/{scope.get('product')}/{scope.get('account_mode')}"
        for detail in (details if isinstance(details, list) else []) if isinstance(detail, dict)
        for scope in detail.get("execution_scopes", []) if isinstance(detail.get("execution_scopes"), list)
        if f"| {detail.get('id')} | {scope.get('venue')} | {scope.get('product')} | {scope.get('account_mode')} |" not in markdown
    ]
    missing_account_scope_rows = [
        f"{detail.get('id')}/{scope.get('venue')}/{scope.get('product')}"
        for detail in (details if isinstance(details, list) else []) if isinstance(detail, dict)
        for scope in detail.get("account_query_scopes", []) if isinstance(scope, dict)
        for account_model in scope.get("account_models", [])
        if f"| {detail.get('id')} | {scope.get('venue')} | {scope.get('product')} | {account_model}" not in markdown
    ]
    check(
        bool(markdown)
        and expected_digest_marker in markdown
        and not missing_markdown_ids
        and not missing_scope_rows
        and not missing_account_scope_rows,
        "README 所链接的能力表由当前三份来源生成，版本摘要、stable ID、交易与账户查询范围均在表中",
        f"缺失 stable ID {missing_markdown_ids}；缺失交易范围 {missing_scope_rows}；缺失账户查询范围 {missing_account_scope_rows}；来源摘要匹配 {expected_digest_marker in markdown}",
    )
    readme = _text_or_empty(ROOT / "README.md")
    deploy_readme = _text_or_empty(ROOT / "deploy/README.md")
    capability_html = _text_or_empty(ROOT / "web/console/index.html")
    capability_script = _text_or_empty(ROOT / "web/console/app.js")
    capability_ui_filters = (
        all(
            f'id="product-capability-{field}"' in capability_html
            for field in ("id", "venue", "product", "account-mode", "account-model", "margin-mode", "operation")
        )
        and "execution_scope_facets" in capability_script
        and all(
            f'"{field}", "product-capability-{element}"' in capability_script
            for field, element in (
                ("capability_id", "id"),
                ("venue", "venue"),
                ("product", "product"),
                ("account_mode", "account-mode"),
                ("account_model", "account-model"),
                ("margin_mode", "margin-mode"),
                ("operation", "operation"),
            )
        )
        and "API_PATHS.productCapabilityQuery, query" in capability_script
    )
    check(
        "docs/capability-catalog.md" in readme
        and "qx-cli doctor --capabilities" in readme
        and "--account-mode hedge" in readme
        and "doctor --capabilities --capability-id" in deploy_readme
        and "POST /app/capabilities/query" in deploy_readme
        and '"account_mode":"hedge"' in deploy_readme,
        "README 与部署 API 文档均链接统一能力目录、列出离线 CLI 与范围查询入口",
        "产品能力发现入口未在用户文档和部署 API 文档同时出现",
    )
    check(
        capability_ui_filters,
        "Web 控制台暴露目录筛选项并把已填筛选条件发送到统一查询 API",
        "Web 能力查询表单、筛选维度或请求出口脱节",
    )


# ---- 主链路调用图 + 孤儿/重复逻辑清单（方案 §5.1/§5.2/§5.4；§7 阶段 0；§13.2）----
#
# 方案 §7 阶段 0 的交付物里，「三条主链路调用图」与能力矩阵并列；§13.2 明写「完成阶段 0，并将能力
# 矩阵和**接口调用图**纳入仓库版本控制」。方案 §5.1/§5.2/§5.4 用箭头写了三条主链，但那三段文字
# 没有任何东西把每一段钉在真实符号上——符号改名、文件搬家、用例删掉，三段箭头照旧读起来很完整，
# 而「文档替不存在的代码作保」正是本仓反复栽过的那一类。
#
# 这一族的两个方向刻意相反，缺一不可：
#   * `steps` 里每条 anchor 必须在**它自己文件之外**出现过——否则那一步在链路上没有下游；
#   * `orphans` 里 `kind: no_production_consumer` 的每条必须在**它自己文件之外**找不到消费者
#     ——否则这条"孤儿"记录是假的。
# 只做前一向会放过"把不存在的调用画进图里"；只做后一向会放过"把活着的东西记成孤儿"。
CHAIN_MAP_FILE = "maturity/chain-map.yaml"
CHAIN_MAP_KIND = "chain-map"
CHAIN_MAP_CHAINS = (
    "data_to_research_backtest",
    "paper_live_order_loop",
    "multi_language_strategy",
)
CHAIN_MAP_ORPHAN_KINDS = (
    "no_production_consumer",
    "duplicate_declaration",
    "dead_route",
    "unused_export",
)
CHAIN_MAP_ORPHAN_DISPOSITIONS = (
    "retained_public_api",
    "allowlisted",
    "pending_removal",
)
# 声明规则按语言分：Rust 认 fn/const/struct/enum/static/type/trait，Python 认 class/def。
# 同一把尺也是 `http_surface_check` 用的那把（那边只有 Rust 锚点）。
CHAIN_DECLARATION_RULE = {
    ".rs": r"\b(?:fn|const|struct|enum|static|type|trait)\s+{name}\b",
    ".py": r"\b(?:class|def)\s+{name}\b",
}
_CHAIN_TEXT_CACHE: dict[str, str] | None = None


def _chain_production_texts() -> dict[str, str]:
    """全仓生产文本（`crates/**/*.rs` 与 `python/**/*.py`），一次读齐。

    Python 侧只排除 `build/` 与 `__pycache__`——它们是构建产物，不是仓库里的第二份实现。
    """
    global _CHAIN_TEXT_CACHE
    if _CHAIN_TEXT_CACHE is None:
        cache: dict[str, str] = {}
        for pattern in ("crates/**/*.rs", "python/**/*.py"):
            for path in sorted(ROOT.glob(pattern)):
                relative = path.relative_to(ROOT).as_posix()
                if (
                    TEST_PATH.search(relative)
                    or "/build/" in relative
                    or "__pycache__" in relative
                ):
                    continue
                body = _read_text(path)
                cache[relative] = production_text(body) if path.suffix == ".rs" else body
        _CHAIN_TEXT_CACHE = cache
    return _CHAIN_TEXT_CACHE


def _chain_symbol_outside(relative: str, symbol: str) -> list[str]:
    """`symbol` 在**别的文件**的生产文本里出现的位置（相对路径列表）。"""
    return [
        other
        for other, body in _chain_production_texts().items()
        if other != relative and re.search(rf"\b{re.escape(symbol)}\b", body)
    ]


def _chain_declared(relative: str, symbol: str) -> bool:
    """符号是否真在那个文件里声明（按后缀选 Rust / Python 的声明规则）。"""
    body = _chain_production_texts().get(relative)
    if body is None:
        return False
    rule = CHAIN_DECLARATION_RULE[".py" if relative.endswith(".py") else ".rs"]
    return re.search(rule.format(name=re.escape(symbol)), body) is not None


def chain_map_check() -> None:
    """方案 §7 阶段 0 的「三条主链路调用图」+「孤儿/重复逻辑清单」与真实符号对账。

    十一颗：① 调用图在盘、自述 kind 与 schema_version 正确、三段（chains/steps/orphans）非空；
    ② `chains` 名册 == 方案 §5.1/§5.2/§5.4 点名的三条主链；③ 每条 step 的 `chain` 都是声明过的链；
    ④ 每条链内 step 的 `order` 恰好是 1..N（无缺号、无重号）；⑤ 每条 step 的 `anchor` 文件在盘且
    符号真在其中声明（Rust 认 fn/const/struct/enum/static/type/trait，`.py` 认 class/def）；
    ⑥ 每条 step 的 `case` 用例真在那个文件里（**读原文**——用例按定义就在 `#[cfg(test)]` 里，
    剥测试项的读法会把它们全判成不存在）；⑦ 每条链的 `entry`/`terminal` 都是链内真实存在的 step 名；
    ⑧ 每条链的 `evidence` 逐条在盘；⑨ **声明不是装饰**——每条 step 的 anchor 符号必须在它自己
    文件之外的生产文本里出现过（只在定义处出现的符号说明这一步在链路上没有下游）；
    ⑩ 每条 orphan 的 anchor 能解析、`kind` 与 `disposition` 都落在闭集里；
    ⑪ **孤儿记录必须是真的**——`kind: no_production_consumer` 的条目真的在它自己文件之外找不到
    消费者，且没有任何链上 step 被同时记成孤儿（同一条红的两面）。刻意不早退：恒发十一条。
    """
    sections = _parse_named_records(ROOT / CHAIN_MAP_FILE, ("chains", "steps", "orphans"))
    chains, steps, orphans = sections["chains"], sections["steps"], sections["orphans"]
    text = _text_or_empty(ROOT / CHAIN_MAP_FILE)
    declared_kind = re.search(r"^kind:\s*(\S+)\s*$", text, re.MULTILINE)
    declared_schema = re.search(r"^schema_version:\s*(\d+)\s*$", text, re.MULTILINE)
    check(
        declared_kind is not None
        and declared_kind.group(1) == CHAIN_MAP_KIND
        and declared_schema is not None
        and declared_schema.group(1) == "1"
        and bool(chains)
        and bool(steps)
        and bool(orphans),
        "主链路调用图在盘、自述 kind 与 schema_version 正确、三段（chains/steps/orphans）非空",
        f"kind {declared_kind and declared_kind.group(1)}；"
        f"schema {declared_schema and declared_schema.group(1)}；"
        f"chains {len(chains)} / steps {len(steps)} / orphans {len(orphans)}",
    )

    chain_names = [str(chain.get("name", "")) for chain in chains]
    check(
        len(chain_names) == len(set(chain_names))
        and set(chain_names) == set(CHAIN_MAP_CHAINS),
        "`chains` 名册 == 方案 §5.1/§5.2/§5.4 点名的三条主链",
        f"缺 {sorted(set(CHAIN_MAP_CHAINS) - set(chain_names))}；"
        f"多 {sorted(set(chain_names) - set(CHAIN_MAP_CHAINS))}",
    )

    strays = [
        str(step.get("name"))
        for step in steps
        if str(step.get("chain", "")) not in chain_names
    ]
    check(
        not strays,
        "每条 step 的 `chain` 都是声明过的链（挂在不存在链上的步骤不会出现在任何链路里）",
        f"悬空 {strays}；已声明链 {chain_names}",
    )

    order_gaps: list[str] = []
    for name in chain_names:
        orders = sorted(
            int(str(step.get("order", "0")))
            for step in steps
            if str(step.get("chain", "")) == name
        )
        if orders != list(range(1, len(orders) + 1)):
            order_gaps.append(f"{name}:{orders}")
    check(
        not order_gaps,
        "每条链内 step 的 `order` 恰好是 1..N（无缺号、无重号）",
        f"异常 {order_gaps or '无'}",
    )

    anchor_gaps: list[str] = []
    for step in steps:
        relative, _, symbol = str(step.get("anchor", "")).partition(" ")
        if not relative or not symbol or not _chain_declared(relative, symbol):
            anchor_gaps.append(f"{step.get('name')}（{step.get('anchor')}）")
    check(
        not anchor_gaps,
        "每条 step 的 `anchor` 文件在盘且符号真在其中声明（Rust 认 fn/const/struct/…，`.py` 认 class/def）",
        f"对不上 {anchor_gaps or '无'}",
    )

    # case 读**原文**：用例按定义就住在 `#[cfg(test)]` 里，剥测试项的读法会把它们全判成不存在。
    case_gaps: list[str] = []
    for step in steps:
        relative, _, test_fn = str(step.get("case", "")).partition(" ")
        target = ROOT / relative
        if (
            not relative
            or not test_fn
            or not target.is_file()
            or re.search(
                rf"\b(?:fn|def)\s+{re.escape(test_fn)}\b", target.read_text(encoding="utf-8")
            )
            is None
        ):
            case_gaps.append(f"{step.get('name')}（{step.get('case')}）")
    check(
        not case_gaps,
        "每条 step 的 `case` 用例真在那个文件里（读原文——用例本来就在 `#[cfg(test)]` 里）",
        f"对不上 {case_gaps or '无'}",
    )

    by_chain: dict[str, set[str]] = {name: set() for name in chain_names}
    for step in steps:
        by_chain.setdefault(str(step.get("chain", "")), set()).add(str(step.get("name", "")))
    endpoint_gaps = [
        f"{chain.get('name')}:{key}={chain.get(key)}"
        for chain in chains
        for key in ("entry", "terminal")
        if str(chain.get(key, "")) not in by_chain.get(str(chain.get("name", "")), set())
    ]
    check(
        not endpoint_gaps,
        "每条链的 `entry`/`terminal` 都是链内真实存在的 step 名",
        f"落空 {endpoint_gaps or '无'}",
    )

    evidence_gaps = [
        f"{chain.get('name')}:{entry}"
        for chain in chains
        for entry in chain.get("evidence", [])
        if not (ROOT / str(entry)).exists()
    ]
    check(
        not evidence_gaps,
        "每条链的 `evidence` 逐条在盘（链路要有一条能复核的证据，不能只有箭头）",
        f"失效 {evidence_gaps or '无'}",
    )

    decoration = [
        f"{step.get('name')}:{symbol}"
        for step in steps
        for relative, _, symbol in [str(step.get("anchor", "")).partition(" ")]
        if relative and symbol and not _chain_symbol_outside(relative, symbol)
    ]
    check(
        not decoration,
        "声明不是装饰——每条 step 的 anchor 符号在它自己文件之外也有生产读者（否则这一步没有下游）",
        f"只在定义处出现 {decoration or '无'}",
    )

    orphan_gaps = [
        f"{orphan.get('name')}（{orphan.get('anchor')}）"
        for orphan in orphans
        for relative, _, symbol in [str(orphan.get("anchor", "")).partition(" ")]
        if not relative or not symbol or not _chain_declared(relative, symbol)
    ] + [
        f"{orphan.get('name')}:kind={orphan.get('kind')}"
        for orphan in orphans
        if str(orphan.get("kind", "")) not in CHAIN_MAP_ORPHAN_KINDS
    ] + [
        f"{orphan.get('name')}:disposition={orphan.get('disposition')}"
        for orphan in orphans
        if str(orphan.get("disposition", "")) not in CHAIN_MAP_ORPHAN_DISPOSITIONS
    ]
    check(
        not orphan_gaps,
        "每条 orphan 的 anchor 能解析，且 `kind` 与 `disposition` 都落在闭集里",
        f"问题 {orphan_gaps or '无'}",
    )

    step_symbols = {
        (str(step.get("anchor", "")).partition(" ")[0], str(step.get("anchor", "")).partition(" ")[2])
        for step in steps
    }
    fake_orphans: list[str] = []
    for orphan in orphans:
        relative, _, symbol = str(orphan.get("anchor", "")).partition(" ")
        if not relative or not symbol:
            continue
        if (relative, symbol) in step_symbols:
            fake_orphans.append(f"{orphan.get('name')}:同时挂在链上")
        elif str(orphan.get("kind", "")) == "no_production_consumer":
            outside = _chain_symbol_outside(relative, symbol)
            if outside:
                fake_orphans.append(f"{orphan.get('name')}:外面有读者 {outside[:3]}")
    check(
        not fake_orphans,
        "孤儿记录必须是真的——`no_production_consumer` 在外面真找不到读者，且没有链上步骤被记成孤儿",
        f"不成立 {fake_orphans or '无'}",
    )


# —— 方案 §6.1：第三方 Rust 门面 crate `qx-sdk` ——
#
# 立案的是「第三方稳定边界」这一格此前**完全不存在**：`qx-app` 是按用例组织、为三个门面
# （CLI / HTTP / Python）服务的应用层，不是给仓库外调用方用的边界。集成方只能自己挑
# `qx-app` 加若干领域 crate 拼，拼错了没人拦；方案 §6.1 要的 semver 承诺、迁移指南、
# examples 与独立消费者构建，一样都没有。
#
# 这一族刻意**不**靠"读散文"判定覆盖：名册逐条写成 `<门面符号> <- <源 crate>::<源符号>`，
# 两个方向都核——门面符号必须真出现在门面源码里（否则是"文档说有、代码没有"），
# 源符号必须真在源 crate 的公开面里（否则是凭空声明）。
SDK_FACADE_DIR = "crates/qx-sdk"
SDK_FACADE_LIB = "crates/qx-sdk/src/lib.rs"
SDK_FACADE_CONSUMER = "crates/qx-sdk/tests/independent_consumer.rs"
SDK_FACADE_EXAMPLE = "crates/qx-sdk/examples/quickstart.rs"
SDK_FACADE_MIGRATION_DOC = "docs/qx-sdk-migration.md"
# 门面的内部依赖必须**恰好**是这几个：qx-app（它要门面的那一层）加 §6.1 点名的两个端口 crate，
# 外加 qx-strategy（`BuiltinStrategyKind` 是 `BuiltinStrategySpec::new` 的参数类型，而 qx-app
# 没有重导出它）。多一个 = 门面开始拼接领域 crate，那正是 §6.1 要消灭的形状。
SDK_FACADE_ALLOWED_INTERNAL_DEPS = ("qx-app", "qx-execution", "qx-provider", "qx-strategy")
# 门面里**不得**出现业务逻辑：每个 `pub fn` 的函数体（非空非注释行）不超过这么多行。
# 数字取 4 是因为最长的那个是 `Client::new` 的结构体字面量（`Self {` + 一行字段 + `}`）。
SDK_FACADE_MAX_BODY_LINES = 4
