def stdout_json_error_propagation_check() -> None:
    smoke = _text_or_empty(ROOT / "crates/qx-cli/src/ecosystem_smoke.rs")
    json_output = _text_or_empty(ROOT / "crates/qx-cli/src/ecosystem_smoke/json_output.rs")
    selfcheck = _text_or_empty(ROOT / "crates/qx-cli/src/selfcheck.rs")
    cli = _text_or_empty(ROOT / "crates/qx-cli/src/cli.rs")
    export = _text_or_empty(ROOT / "crates/qx-cli/src/run_evidence_export.rs")
    verify = _text_or_empty(ROOT / "crates/qx-cli/src/run_evidence_verify.rs")
    no_stdout_expect = all(
        phrase not in json_output
        for phrase in (
            'expect("JSON report writes to stdout")',
            'expect("JSON report newline writes to stdout")',
            'expect("JSON result writes to stdout")',
            'expect("JSON result newline writes to stdout")',
        )
    )
    check(
        "pub(crate) fn print_json_report(report: &serde_json::Value) -> Result<(), String>"
        in json_output
        and "pub(crate) fn print_machine_json(report: &serde_json::Value) -> Result<(), String>"
        in json_output
        and no_stdout_expect
        and "print_json_report(&report)?;" in smoke
        and selfcheck.count("print_json_report(&report)?;") == 2
        and "pub(crate) fn run(scope: Scope, as_json: bool) -> Result<(), String>" in selfcheck
        and "}))?;" in export
        and "}))?;" in verify
        and "fn dispatch_output_result(result: Result<(), String>, command: &str)" in cli
        and '"生态自检"' in cli
        and '"全量自检"' in cli
        and '"内核自检"' in cli,
        "JSON stdout I/O failures propagate as CLI errors instead of panicking",
        f"JSON writers are fallible={'Result<(), String>' in json_output}; stdout expect removed={no_stdout_expect}; selfcheck consumers={selfcheck.count('print_json_report(&report)?;')}/2",
    )


def runtime_invariant_error_propagation_check() -> None:
    worker_risk = _text_or_empty(ROOT / "crates/qx-service/src/risk_host.rs")
    fx_resolver = worker_risk[
        worker_risk.find("pub fn spot_fx_rates_to_reporting(") :
        worker_risk.find("fn fx_currency_distances(")
    ]
    comparison = _text_or_empty(ROOT / "crates/qx-cli/src/report_comparison_command.rs")
    depth_quality = _text_or_empty(ROOT / "crates/qx-app/src/cases/run_depth_backtest/quality.rs")
    app_runs = _fn_body(
        _text_or_empty(ROOT / "crates/qx-api/src/app_runs.rs"),
        "fn reserve(&self, run_id: String)",
    )
    watcher_slot = _text_or_empty(ROOT / "crates/qx-api/src/app_runs/persistence.rs")
    ws = _text_or_empty(ROOT / "crates/qx-api/src/ws.rs")
    api = production_text(_text_or_empty(ROOT / "crates/qx-api/src/lib.rs"))
    api_tight = re.sub(r"\s+", "", api)
    check(
        "let Some(shortest_distance) = distance_from_source.get(&reporting).copied() else" in fx_resolver
        and "FAIL_CLOSED: 缺少 {source}->{reporting} 可用 Spot FX 路径与标记价" in fx_resolver
        and "rate_to_currency.get(&reporting).copied().ok_or_else" in fx_resolver
        and ".unwrap()" not in fx_resolver
        and "等长但不一致的 FX 路径" in fx_resolver,
        "Paper FX 多跳解析对空路径/状态缺失/等长报价冲突 fail-closed，不假设集合非空",
    )
    check(
        'identity.ok_or_else(|| "横向对照输入身份未建立".to_string())?' in comparison
        and 'identity.expect("至少两份摘要已通过加载")' not in comparison,
        "横向报告身份缺失返回 CLI 错误，不以 expect panic",
    )
    check(
        "let Some(start_timestamp) = timestamps.iter().min() else" in depth_quality
        and "let Some(end_timestamp) = timestamps.iter().max() else" in depth_quality
        and "timestamps.iter().min().expect" not in depth_quality
        and "timestamps.iter().max().expect" not in depth_quality,
        "深度质量报告对空时间轴具名拒绝，不以 min/max expect panic",
    )
    check(
        "entries.get_mut(&run_id)" in app_runs
        and 'AppErrorCategory::InternalInvariant' in app_runs
        and "entries.get_mut(&run_id).unwrap()" not in app_runs
        and "persistence::WatcherSlot(self.watcher_counter)" in app_runs
        and "watcher_slot," in app_runs
        and "entries.remove(&run_id);" in app_runs
        and "impl Drop for WatcherSlot" in watcher_slot
        and "self.0.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);" in watcher_slot,
        "异步运行注册表项意外缺失时返回 InternalInvariant，观察器名额由 WatcherSlot RAII 释放",
    )
    check(
        "self.pending.get(mask_start..total)" in ws
        and "<[u8; 4]>::try_from(mask_bytes)" in ws
        and 'expect("masked client frame carries a four-byte key")' not in ws
        and ws.count("result.closed = true;") >= 3,
        "WebSocket Ping 掩码长度异常时关闭连接，不因客户端帧头形状 panic",
    )
    check(
        "pub fn current(&self) -> Result<Arc<ServerConfig>, String>" in api
        and "pub fn current(&self) -> Result<Arc<MtlsIdentityPolicy>, String>" in api
        and "TLS config store lock poisoned" in api
        and "mTLS identity store lock poisoned" in api
        and 'read().expect("TLS config store lock poisoned")' not in api_tight
        and 'read().expect("mTLS identity store lock poisoned")' not in api_tight,
        "TLS/mTLS 热替换 store 锁中毒返回错误，不在身份/配置读取时 panic",
    )
    check(
        'expect("TLS PEM reloader lock poisoned")' not in api_tight
        and 'expect("mTLS identity reloader lock poisoned")' not in api_tight
        and "store.replace(config)?;" in api
        and "store.replace(policy)?;" in api
        and "读取 TLS 配置失败" in api
        and "读取 mTLS 身份策略失败" in api,
        "TLS/mTLS reload 锁错误可传播，服务握手入口遇 poison 时失败关闭",
    )
    check(
        "MutexPoisoned" in api
        and "CondvarPoisoned" in api
        and "pub fn next_seq(&self) -> Result<u64, EventBusError>" in api
        and 'expect("event bus mutex poisoned")' not in api_tight
        and 'expect("event bus condvar poisoned")' not in api_tight
        and "读取账户投影事件总线序号失败" in api
        and "读取 API 投影事件总线序号失败" in api
        and "读取 API 内部事件总线序号失败" in api,
        "API EventBus 的 Mutex/Condvar poison 与 next_seq 通过错误类型传播至投影边界",
    )
    qx_api_root = ROOT / "crates/qx-api/src"
    qx_api_panics = []
    for path in sorted(qx_api_root.rglob("*.rs")):
        source = _read_text(path)
        if (
            "tests" in path.parts
            or path.stem.endswith("_tests")
            or source.lstrip().startswith("#![cfg(test)]")
        ):
            continue
        production = production_text(source)
        for line_number, line in enumerate(production.splitlines(), 1):
            if re.search(r"\.(?:unwrap|expect)\s*\(", line):
                qx_api_panics.append(f"{path.relative_to(ROOT)}:{line_number}")
    check(
        not qx_api_panics,
        "qx-api 生产源码（测试作用域剥离后）没有显式 unwrap/expect panic",
        f"残留调用 {qx_api_panics[:12] or '无'}",
    )
    check(
        "pub(crate) fn serialized_json_response<T: Serialize>" in api
        and "API JSON serialization failed" in api
        and "Err(error) => ApiResponse::json" in api,
        "qx-api typed JSON serialization failures return a 500 response with context",
    )


# ---- WP-1 产物发布单点（docs/...-2026-10-19.md §5.3）----
# 审计前全仓有 5 处「自造临时文件 + 发布」的实现（rename / hard_link / create_new 三种
# 语义各不相同）、外加 6 处裸 `fs::write`：同一次运行的两份产物在「并发重跑时是报冲突
# 还是静默覆盖」上行为不一致。收敛后，产物发布只走 `qx_app::artifact_store::sink` 一个原语，
# 三种语义（Idempotent / CreateNew / Overwrite）枚举齐全并写入注释。
ARTIFACT_SINK_FILE = "crates/qx-app/src/artifact_store/sink.rs"
ARTIFACT_SINK_DEFS = (
    re.compile(r"^pub enum PublishMode \{"),
    re.compile(r"^pub enum PublishError \{"),
    re.compile(r"^pub struct TempPublish \{"),
    re.compile(r"^pub fn publish\("),
    re.compile(r"^pub fn publish_bytes\("),
    re.compile(r"^pub fn publish_stream[<(]"),
)
# 登记表：写产物的生产文件。改这个集合必须同轮改判据（否则「实际 vs 登记」立刻分叉）。
ARTIFACT_PUBLISH_CALLERS = (
    "crates/qx-app/src/artifact_store/backtest_summary.rs",
    "crates/qx-app/src/artifact_store/run_record.rs",
    "crates/qx-app/src/artifact_store/portable_run_evidence.rs",
    "crates/qx-app/src/cases/artifacts.rs",
    "crates/qx-app/src/cases/run_provider_backtest_with_manifest.rs",
    "crates/qx-app/src/cases/validate_dataset_manifest.rs",
    "crates/qx-app/src/cases/validate_depth_dataset_manifest.rs",
    # WP-1 收网时指纹扫描抓到的第六处（审计漏项）：app 运行注册表的 RunSnapshot 落盘，
    # 与 run_record.rs 是同一类事实件（一份运行的权威状态记录），一并收编到 sink。
    "crates/qx-api/src/app_runs/persistence.rs",
    "crates/qx-cli/src/report_html.rs",
    "crates/qx-cli/src/report_xlsx/openxml.rs",
    "crates/qx-cli/src/report_comparison.rs",
    "crates/qx-cli/src/report_benchmark.rs",
    "crates/qx-cli/src/report_comparison_benchmark.rs",
    "crates/qx-cli/src/report_multi_market_depth.rs",
    "crates/qx-cli/src/run_evidence_experiment_recompute/portable_bundle.rs",
)
# 「自造临时文件 + 发布」的指纹：hard_link 发布、或 with_extension 造临时名后 rename/write。
SELF_ROLLED_PUBLISH = (
    re.compile(r"fs::hard_link\("),
    re.compile(r"with_extension\(format!"),
    re.compile(r"\.tmp-"),
)
# 豁免登记表：带自搓发布形状、但**不是**产物落盘的运行期/数据层写点，每项一条理由。
# 转走 sink 的那天把条目移出去——(d) 盯着「已无指纹还赖在表里」。qx-data 三处与
# qx-zhenlu 还有结构性理由：sink 住在 qx-app，而这些 crate 在依赖序上位于 qx-app
# 下游（qx-app 的依赖清单里有它们，反向不成立），发布原语下沉是独立议题。
ARTIFACT_PUBLISH_EXEMPT = {
    "crates/qx-service/src/ccxt_live_bars.rs": "实时 BarFrame 快照：行情运行期断点，每轮整份覆写，不是一次运行的产物",
    "crates/qx-cli/src/strategy_live_state.rs": "实时策略 digest 断点：运行期状态，非产物",
    "crates/qx-cli/src/workers/strategy_worker/execution_updates.rs": "策略 EventLog 消费游标：运行期可恢复状态，非研究/回测产物",
    "crates/qx-service/src/worker_metrics.rs": "worker Prometheus .prom 边车文件：运维指标出口，非产物（WP-3.14）",
    "crates/qx-data/src/catalog.rs": "数据集目录登记：数据层存储，sink 在 qx-app、qx-data 位于其下游",
    "crates/qx-data/src/registry.rs": "数据集注册表：数据层存储，同上",
    "crates/qx-data/src/storage.rs": "Bar 存储落盘：数据层存储，同上",
    "crates/qx-zhenlu/src/lib.rs": "多腿组合单状态：FileLock 保护的活单运行期状态，非产物",
}


def artifact_publish_single_exit_check() -> None:
    """产物发布只有一个出口：`qx_app::artifact_store::sink`（WP-1）。

    这一族判的不是「现在写坏了没有」，而是**下一次新写一处产物落盘时会不会又被放过去**：
    定义点唯一、调用方全部登记、且任何生产文件都不许再用手搓的临时文件发布。
    """
    production = {
        rel: text
        for rel, text in _production_sources().items()
    }
    # (a) 每个发布原语只有一个定义点，且都住在 sink。
    for pattern in ARTIFACT_SINK_DEFS:
        definitions = sorted(rel for rel, lines in production.items() if any(pattern.match(line) for line in lines))
        check(
            definitions == [ARTIFACT_SINK_FILE],
            f"产物发布原语 {pattern.pattern} 只定义于 {ARTIFACT_SINK_FILE}",
            f"定义于 {definitions}",
        )
    # (b) 登记表里的每个文件都真的经 sink 发布（同轮改登记会立刻分叉）。
    for rel in ARTIFACT_PUBLISH_CALLERS:
        text = production.get(rel)
        check(
            text is not None,
            f"产物发布调用方登记表条目在盘：{rel}",
            f"缺失 {rel}",
        )
        if text is None:
            continue
        joined = "\n".join(text)
        check(
            "sink::" in joined,
            f"{rel} 的产物落盘走 sink 出口",
            f"{rel} 未引用 sink",
        )
        rolled = [pattern.pattern for pattern in SELF_ROLLED_PUBLISH if pattern.search(joined)]
        check(
            not rolled,
            f"{rel} 不再自造临时文件发布（手搓发布已收编）",
            f"{rel} 仍有自搓发布指纹 {rolled}",
        )
    # (c) 全仓任何生产文件都不许出现新的自搓发布形状：要么走 sink（登记在 CALLERS），
    # 要么进豁免登记表写明「为什么它不是产物落盘」。两条都沾不上即失败——这就是
    # 「下一次新写一处产物落盘会不会又被放过去」那颗牙。
    offenders = sorted(
        rel
        for rel, lines in production.items()
        if rel != ARTIFACT_SINK_FILE
        and rel not in ARTIFACT_PUBLISH_CALLERS
        and rel not in ARTIFACT_PUBLISH_EXEMPT
        and any(pattern.search("\n".join(lines)) for pattern in SELF_ROLLED_PUBLISH)
    )
    check(
        not offenders,
        "未登记的自搓发布形状为空（新写一处落盘必须走 sink 或进豁免登记表）",
        f"未登记的自搓发布 {offenders}",
    )
    # (d) 豁免登记表两向咬合：条目在盘；且条目仍带指纹（转走 sink 后不许赖在表里）。
    # 没有这一颗，「临时豁免」会悄悄长成永久例外。
    for rel, reason in ARTIFACT_PUBLISH_EXEMPT.items():
        text = production.get(rel)
        check(text is not None, f"豁免登记表条目在盘：{rel}", f"缺失 {rel}")
        if text is None:
            continue
        check(
            any(pattern.search("\n".join(text)) for pattern in SELF_ROLLED_PUBLISH),
            f"豁免条目仍带自搓指纹（转走 sink 后请移出登记表）：{rel}",
            f"{rel} 已无自搓指纹，请移出 ARTIFACT_PUBLISH_EXEMPT（原由：{reason}）",
        )


def _main_check_functions() -> tuple[tuple[str, object], ...]:
    """Return the ordered structural check calls from main without duplicating their roster."""
    source = _read_text(Path(__file__).resolve())
    tree = ast.parse(source)
    main_node = next(node for node in tree.body if isinstance(node, ast.FunctionDef) and node.name == "main")
    names = [
        statement.value.func.id
        for statement in main_node.body
        if isinstance(statement, ast.Expr)
        and isinstance(statement.value, ast.Call)
        and isinstance(statement.value.func, ast.Name)
        and statement.value.func.id.endswith("_check")
    ]
    return tuple((name, globals()[name]) for name in names)


def _shard_options() -> tuple[int, int, Path] | None:
    if "--fast" in sys.argv:
        if sys.argv[1:] != ["--fast"]:
            raise ValueError("--fast cannot be combined with other options")
        return None
    values: dict[str, str] = {}
    index = 1
    while index < len(sys.argv):
        argument = sys.argv[index]
        if argument in ("--shard", "--report"):
            if index + 1 >= len(sys.argv):
                raise ValueError(f"{argument} requires a value")
            values[argument] = sys.argv[index + 1]
            index += 2
            continue
        if argument.startswith("--shard="):
            values["--shard"] = argument.split("=", 1)[1]
        elif argument.startswith("--report="):
            values["--report"] = argument.split("=", 1)[1]
        else:
            raise ValueError(f"unknown argument: {argument}")
        index += 1

    if "--shard" not in values:
        if "--report" in values:
            raise ValueError("--report is only valid with --shard")
        return None
    if "--report" not in values:
        raise ValueError("--shard requires --report")
    match = re.fullmatch(r"(\d+)/(\d+)", values["--shard"])
    if not match:
        raise ValueError("--shard must be K/N with zero-based K")
    shard, count = map(int, match.groups())
    if count < 2 or shard >= count:
        raise ValueError("--shard requires N >= 2 and 0 <= K < N")
    return shard, count, Path(values["--report"])


def _run_fast() -> int:
    """Run every architecture predicate in parallel shards and verify the full roster."""
    shard_count = 4
    started = time.perf_counter()
    with tempfile.TemporaryDirectory(prefix="qx-architecture-fast-") as directory:
        report_dir = Path(directory)

        def run_shard(shard: int) -> subprocess.CompletedProcess[str]:
            return subprocess.run(
                [
                    sys.executable,
                    str(Path(__file__).resolve()),
                    "--shard",
                    f"{shard}/{shard_count}",
                    "--report",
                    str(report_dir / f"shard-{shard}.json"),
                ],
                cwd=ROOT,
                capture_output=True,
                text=True,
                encoding="utf-8",
                errors="replace",
                check=False,
            )

        with ThreadPoolExecutor(max_workers=shard_count) as executor:
            results = list(executor.map(run_shard, range(shard_count)))
        for shard, result in enumerate(results):
            if result.returncode != 0:
                print(result.stdout, end="")
                print(result.stderr, end="", file=sys.stderr)
                print(f"架构快速分片 {shard}/{shard_count} 失败：exit {result.returncode}")
                return result.returncode or 1
        aggregate = subprocess.run(
            [
                sys.executable,
                str(ROOT / "tools" / "verify_architecture_shards.py"),
                str(report_dir),
                str(shard_count),
            ],
            cwd=ROOT,
            check=False,
        )
        if aggregate.returncode != 0:
            return aggregate.returncode
    elapsed = time.perf_counter() - started
    print(f"架构 --fast 完成：全量判据四片执行并聚合，墙钟 {elapsed:.2f}s")
    return 0


def _run_shard(shard: int, shard_count: int, report_path: Path) -> int:
    function_reports = []
    for ordinal, (name, function) in enumerate(_main_check_functions()):
        if ordinal % shard_count != shard:
            continue
        first_label = len(labels)
        function()
        function_reports.append({"ordinal": ordinal, "name": name, "labels": labels[first_label:]})
    report = {
        "schema_version": 1,
        "shard": shard,
        "shards": shard_count,
        "checks": checks,
        "failures": failures,
        "functions": function_reports,
    }
    report_path.parent.mkdir(parents=True, exist_ok=True)
    report_path.write_text(json.dumps(report, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"\n架构分片 {shard}/{shard_count} 完成：{checks} 项，失败 {len(failures)} 项")
    return 1 if failures else 0


def main() -> int:
    try:
        shard_options = _shard_options()
    except ValueError as error:
        print(f"架构门禁参数错误：{error}")
        return 2
    if shard_options is not None:
        return _run_shard(*shard_options)
    if "--fast" in sys.argv:
        return _run_fast()
